css:
@keyframes mcl-range-fill { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes mcl-range-pop { from { scale: .55; } to { scale: 1; } }
@keyframes mcl-range-spin { to { rotate: 1turn; } }
@keyframes mcl-range-draw { from { stroke-dashoffset: 14; } to { stroke-dashoffset: 0; } }

.mcl-range {
  /* re-theme with these four */
  --mcl-range-paper: oklch(0.986 0.006 85);
  --mcl-range-ink: oklch(0.255 0.018 60);
  --mcl-range-accent: oklch(0.53 0.095 188);
  --mcl-range-warn: oklch(0.56 0.17 36);

  --mcl-range-mute: color-mix(in oklch, var(--mcl-range-ink) 56%, var(--mcl-range-paper));
  --mcl-range-faint: color-mix(in oklch, var(--mcl-range-ink) 27%, var(--mcl-range-paper));
  /* tints mix toward transparent/black so the hue stays the accent's own */
  --mcl-range-line: color-mix(in oklch, var(--mcl-range-ink) 11%, transparent);
  --mcl-range-hover: color-mix(in oklch, var(--mcl-range-ink) 6.5%, transparent);
  --mcl-range-band: color-mix(in oklch, var(--mcl-range-accent) 16%, transparent);
  --mcl-range-band-pv: color-mix(in oklch, var(--mcl-range-accent) 7%, transparent);
  --mcl-range-deep: color-mix(in oklch, var(--mcl-range-accent) 74%, black);
  --mcl-range-out: cubic-bezier(.2, .9, .25, 1);
  --mcl-range-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mcl-range-cell: clamp(32px, 10.4cqi, 38px);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%;
  display: grid; gap: 12px;
  grid-template-areas: "head" "presets" "cal" "foot";
  padding: 16px 16px 14px;
  border: 1px solid var(--mcl-range-line); border-radius: 16px;
  background: var(--mcl-range-paper); color: var(--mcl-range-ink);
  box-shadow: 0 1px 0 color-mix(in oklch, var(--mcl-range-ink) 5%, transparent),
              0 18px 36px -24px color-mix(in oklch, var(--mcl-range-ink) 40%, transparent);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--mcl-range-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; }
  & :focus-visible { outline: 2px solid var(--mcl-range-ink); outline-offset: 2px; }

  /* ---------- header ---------- */
  & .mcl-range-head {
    grid-area: head; display: grid; align-items: end; column-gap: 12px;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "eyebrow eyebrow" "title count";
  }
  & .mcl-range-eyebrow {
    grid-area: eyebrow; display: flex; align-items: center; gap: 6px; margin: 0 0 3px;
    font-size: 10.5px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--mcl-range-mute);
    & svg { width: 13px; height: 13px; }
  }
  & .mcl-range-title {
    grid-area: title; margin: 0; min-width: 0;
    font-size: clamp(17px, 5.4cqi, 21px); font-weight: 680; letter-spacing: -.018em; line-height: 1.2;
    font-variant-numeric: tabular-nums; text-wrap: balance;
  }
  &[data-empty] .mcl-range-title { color: var(--mcl-range-faint); }
  & .mcl-range-nb { white-space: nowrap; }
  & .mcl-range-count {
    grid-area: count; align-self: center; white-space: nowrap;
    padding: 3px 9px; border-radius: 99px;
    background: var(--mcl-range-band); color: var(--mcl-range-deep);
    font: 600 11.5px/1.3 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
  }
  &[data-picking] .mcl-range-count { background: none; box-shadow: inset 0 0 0 1px var(--mcl-range-band); }

  /* ---------- presets ---------- */
  & .mcl-range-presets {
    grid-area: presets; display: flex; gap: 6px; margin: 0 -16px; padding: 2px 16px;
    overflow-x: auto; scrollbar-width: none; scroll-snap-type: x proximity; scroll-padding-inline: 16px;
    mask-image: linear-gradient(90deg, transparent, #000 14px, #000 calc(100% - 28px), transparent);
    &::-webkit-scrollbar { display: none; }
    & button {
      flex: none; scroll-snap-align: start; height: 28px; padding: 0 11px; cursor: pointer;
      border: 1px solid var(--mcl-range-line); border-radius: 99px; background: var(--mcl-range-paper);
      font-size: 12px; font-weight: 520; white-space: nowrap;
      transition: background-color .18s, color .18s, border-color .18s, scale .3s var(--mcl-range-spring);
      &:hover { background: var(--mcl-range-hover); }
      &:active { scale: .96; }
      &[aria-pressed="true"] { background: var(--mcl-range-ink); border-color: var(--mcl-range-ink); color: var(--mcl-range-paper); }
    }
  }

  /* ---------- calendar ---------- */
  & .mcl-range-cal { grid-area: cal; position: relative; }
  & .mcl-range-nav {
    position: absolute; top: -3px; z-index: 2; width: 28px; height: 28px; padding: 0; cursor: pointer;
    display: grid; place-items: center; border: 0; border-radius: 50%; background: none;
    transition: background-color .15s, translate .3s var(--mcl-range-spring);
    & svg { width: 15px; height: 15px; }
    &:hover:not(:disabled) { background: var(--mcl-range-hover); }
    &[data-prev] { left: -4px; &:active:not(:disabled) { translate: -2px 0; } }
    &[data-next] { right: -4px; &:active:not(:disabled) { translate: 2px 0; } }
    &:disabled { color: var(--mcl-range-faint); cursor: default; }
  }
  & .mcl-range-months { --mcl-range-n: 1; --mcl-range-dir: 0; display: grid; grid-template-columns: minmax(0, 1fr); gap: 22px; }
  & .mcl-range-month + .mcl-range-month { display: none; }
  & .mcl-range-mname {
    margin: 0 0 8px; height: 22px; line-height: 22px; text-align: center;
    font-size: 13px; font-weight: 650; letter-spacing: -.005em;
    transition: opacity .3s var(--mcl-range-out), translate .4s var(--mcl-range-out);
    @starting-style { opacity: 0; translate: calc(var(--mcl-range-dir) * 10px) 0; }
  }
  & .mcl-range-grid {
    display: grid; row-gap: 2px;
    transition: opacity .32s var(--mcl-range-out), translate .44s var(--mcl-range-out);
    @starting-style { opacity: 0; translate: calc(var(--mcl-range-dir) * 18px) 0; }
  }
  & .mcl-range-wd, & .mcl-range-row { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); }
  & .mcl-range-wd span {
    height: 20px; display: grid; place-items: center;
    font-size: 10px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--mcl-range-mute);
    &:nth-child(n+6) { color: var(--mcl-range-faint); }
  }
  & .mcl-range-pad { height: var(--mcl-range-cell); }
  & .mcl-range-day {
    position: relative; isolation: isolate; height: var(--mcl-range-cell); padding: 0; border: 0; background: none;
    display: grid; place-items: center; cursor: pointer;
    &::before {
      content: ""; position: absolute; inset: 3px 0; z-index: -1;
      background: var(--mcl-range-band); opacity: 0; transition: opacity .16s;
    }
    & > span {
      position: relative; display: grid; place-items: center;
      width: calc(var(--mcl-range-cell) - 6px); aspect-ratio: 1; border-radius: 50%;
      font-size: 13px; font-weight: 500; font-variant-numeric: tabular-nums;
      transition: background-color .18s, color .18s, box-shadow .18s, scale .45s var(--mcl-range-spring);
    }
    &:hover > span { background: var(--mcl-range-hover); }
    &:active > span { scale: .9; }

    &[data-in]::before { opacity: 1; }
    &[data-s]::before { inset-inline-start: 50%; }
    &[data-e]::before { inset-inline-end: 50%; }
    &[data-s][data-e]::before { opacity: 0; }
    &:first-child::before, .mcl-range-pad + &::before { border-start-start-radius: 99px; border-end-start-radius: 99px; }
    &:last-child::before, &:has(+ .mcl-range-pad)::before { border-start-end-radius: 99px; border-end-end-radius: 99px; }

    /* the range runs on past the month edge: fade the band out instead of capping it */
    &[data-cl]::before { border-radius: 0; mask-image: linear-gradient(90deg, transparent, #000 70%); }
    &[data-cr]::before { border-radius: 0; mask-image: linear-gradient(90deg, #000 30%, transparent); }

    &[data-s] > span, &[data-e] > span { background: var(--mcl-range-accent); color: var(--mcl-range-paper); font-weight: 680; }

    /* previewing while the second date is being picked */
    &[data-pv]::before {
      background: var(--mcl-range-band-pv);
      border-block: 1px dashed color-mix(in oklch, var(--mcl-range-accent) 50%, transparent);
    }
    &[data-pv][data-s] > span, &[data-pv][data-e] > span {
      background: var(--mcl-range-paper); color: var(--mcl-range-deep);
      box-shadow: inset 0 0 0 1.5px var(--mcl-range-accent);
    }
    &[data-pv][data-anchor] > span { background: var(--mcl-range-accent); color: var(--mcl-range-paper); box-shadow: none; }

    &[data-today] > span { padding-bottom: 3px; }
    &[data-today] > span::after {
      content: ""; position: absolute; bottom: 3px; left: 50%; width: 10px; height: 2px; margin-left: -5px;
      border-radius: 2px; background: var(--mcl-range-accent);
    }
    &[data-today][data-s]:not([data-pv]) > span::after, &[data-today][data-e]:not([data-pv]) > span::after,
    &[data-today][data-anchor] > span::after { background: var(--mcl-range-paper); }

    &[aria-disabled="true"] { cursor: not-allowed; color: var(--mcl-range-faint); }
    &[aria-disabled="true"]:hover > span { background: none; }
    &[data-limit] > span {
      background-image: linear-gradient(135deg, transparent 47%, color-mix(in oklch, var(--mcl-range-ink) 9%, transparent) 47% 53%, transparent 53%);
    }

    &:focus-visible { outline: none; }
    &:focus-visible > span { box-shadow: 0 0 0 2px var(--mcl-range-paper), 0 0 0 4px var(--mcl-range-ink); }
  }

  /* sweep the band in, cell by cell, when a range lands */
  & .mcl-range-months.is-wave .mcl-range-day[data-in]::before {
    animation: mcl-range-fill .42s var(--mcl-range-out) backwards;
    animation-delay: calc(min(var(--i, 0), 44) * 11ms);
  }
  & .mcl-range-months.is-wave .mcl-range-day:is([data-s], [data-e]) > span {
    animation: mcl-range-pop .55s var(--mcl-range-spring) backwards;
    animation-delay: calc(min(var(--i, 0), 44) * 11ms);
  }

  /* ---------- footer ---------- */
  & .mcl-range-foot {
    grid-area: foot; display: grid; align-items: center; gap: 10px 8px;
    grid-template-columns: minmax(0, 1fr) auto auto;
    grid-template-areas: "hint hint hint" ". clear apply";
    padding-top: 12px; border-top: 1px solid var(--mcl-range-line);
  }
  & .mcl-range-hint {
    grid-area: hint; margin: 0; min-height: 18px; display: flex; align-items: center; gap: 6px;
    font-size: 12px; color: var(--mcl-range-mute); text-wrap: pretty; font-variant-numeric: tabular-nums;
    & svg { width: 14px; height: 14px; }
    &[data-tone="warn"] { color: var(--mcl-range-warn); font-weight: 520; }
    &[data-tone="ok"] { color: var(--mcl-range-deep); }
  }
  & .mcl-range-clear {
    grid-area: clear; height: 34px; padding: 0 12px; border: 0; border-radius: 10px; background: none; cursor: pointer;
    font-size: 13px; font-weight: 550; color: var(--mcl-range-mute);
    transition: background-color .15s, color .15s;
    &:hover:not(:disabled) { background: var(--mcl-range-hover); color: var(--mcl-range-ink); }
    &:disabled { color: var(--mcl-range-faint); cursor: default; }
  }
  & .mcl-range-apply {
    grid-area: apply; height: 34px; min-width: 96px; padding: 0 15px; border: 0; border-radius: 10px; cursor: pointer;
    display: inline-flex; align-items: center; justify-content: center; gap: 7px;
    background: var(--mcl-range-ink); color: var(--mcl-range-paper);
    font-size: 13px; font-weight: 620;
    transition: background-color .2s, color .2s, scale .35s var(--mcl-range-spring);
    &:active:not(:disabled) { scale: .96; }
    & .mcl-range-spin, & svg { display: none; }
    & svg { width: 15px; height: 15px; stroke-width: 2; }
    &:disabled { cursor: default; }
    &[data-state="off"] { background: var(--mcl-range-line); color: var(--mcl-range-faint); }
    &[data-state="busy"] { background: color-mix(in oklch, var(--mcl-range-ink) 80%, var(--mcl-range-paper)); }
    &[data-state="busy"] .mcl-range-spin {
      display: block; width: 13px; height: 13px; border-radius: 50%;
      border: 2px solid color-mix(in oklch, var(--mcl-range-paper) 30%, transparent); border-top-color: var(--mcl-range-paper);
      animation: mcl-range-spin .7s linear infinite;
    }
    &[data-state="done"] { background: var(--mcl-range-band); color: var(--mcl-range-deep); }
    &[data-state="done"] svg { display: block; stroke-dasharray: 14; animation: mcl-range-draw .45s .05s var(--mcl-range-out) backwards; }
  }

  @container (min-width: 480px) {
    & .mcl-range-foot { grid-template-areas: "hint clear apply"; }
    & .mcl-range-cal { --mcl-range-cell: 36px; }
    & .mcl-range-months { --mcl-range-n: 2; grid-template-columns: repeat(2, minmax(0, 1fr)); }
    & .mcl-range-month + .mcl-range-month { display: block; }
  }
  @container (max-width: 300px) {
    & .mcl-range-brand { display: none; }
    & .mcl-range-day > span { font-size: 12px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mcl-range {
    & .mcl-range-months.is-wave .mcl-range-day[data-in]::before,
    & .mcl-range-months.is-wave .mcl-range-day > span { animation: none; }
    & .mcl-range-grid, & .mcl-range-mname { transition: opacity .2s linear; @starting-style { opacity: 0; translate: none; } }
    & .mcl-range-day > span, & .mcl-range-presets button, & .mcl-range-apply, & .mcl-range-nav { transition: background-color .15s, color .15s; }
    & .mcl-range-apply[data-state="busy"] .mcl-range-spin { animation-duration: 2.4s; }
    & .mcl-range-apply[data-state="done"] svg { animation: none; }
  }
}

js:
const $ = s => root.querySelector(s);
const DAY = 864e5, LIMIT = 90;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const F = o => new Intl.DateTimeFormat('en-US', Object.assign({ timeZone: 'UTC' }, o));
const fShort = F({ month: 'short', day: 'numeric' });
const fYear = F({ month: 'short', day: 'numeric', year: 'numeric' });
const fMonth = F({ month: 'long', year: 'numeric' });
const fLong = F({ weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
const WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const dn = (y, m, d) => Math.round(Date.UTC(y, m, d) / DAY);
const D = n => new Date(n * DAY);
const P = n => { const d = D(n); return { y: d.getUTCFullYear(), m: d.getUTCMonth(), d: d.getUTCDate(), w: (d.getUTCDay() + 6) % 7 }; };
const now = new Date();
const today = dn(now.getFullYear(), now.getMonth(), now.getDate());
const T = P(today);
const monthKey = n => { const p = P(n); return p.y * 12 + p.m; };
const firstOf = k => dn(Math.floor(k / 12), ((k % 12) + 12) % 12, 1);

const monthsEl = $('[data-months]'), presetsEl = $('[data-presets]');
const titleEl = $('[data-title]'), countEl = $('[data-count]'), hintEl = $('[data-hint]');
const applyBtn = $('[data-apply]'), applyLbl = $('[data-applylabel]'), clearBtn = $('[data-clear]');
const prevBtn = $('[data-prev]'), nextBtn = $('[data-next]');
const WARN = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2.2 14.3 13H1.7Z"/><path d="M8 6.4v3M8 11.2v.1"/></svg>';
const OK = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m3.5 8.5 3 3 6-7"/></svg>';

const PRESETS = [
  ['Today', () => [today, today]],
  ['Yesterday', () => [today - 1, today - 1]],
  ['Last 7 days', () => [today - 6, today]],
  ['Last 30 days', () => [today - 29, today]],
  ['This month', () => [dn(T.y, T.m, 1), today]],
  ['Last month', () => [dn(T.y, T.m - 1, 1), dn(T.y, T.m, 0)]],
  ['Last 90 days', () => [today - 89, today]]
];

let start = today - 29, end = today, anchor = null, hover = null, saved = null;
let applied = [start, end], busy = false, cells = [], focusDn = end, view = 0, waveT = 0, lastShown = 0;

const shown = () => parseInt(getComputedStyle(monthsEl).getPropertyValue('--mcl-range-n'), 10) || 1;
const viewFor = n => monthKey(n) - (shown() - 1);
/* one month: show the month holding most of the range; two: end in the right-hand month */
const viewForRange = (a, b) => shown() === 1 ? monthKey(Math.round((a + b) / 2)) : viewFor(b);
const nb = s => '<span class="mcl-range-nb">' + s + '</span>';
const rangeLabel = (a, b) => a === b ? nb(fYear.format(D(a)))
  : P(a).y === P(b).y ? nb(fShort.format(D(a))) + ' – ' + nb(fYear.format(D(b)))
  : nb(fYear.format(D(a))) + ' – ' + nb(fYear.format(D(b)));
/* in running copy, drop the year when both ends fall in the current one */
const shortLabel = (a, b) => P(a).y === T.y && P(b).y === T.y ? (a === b ? fShort.format(D(a)) : fShort.format(D(a)) + ' – ' + fShort.format(D(b))) : rangeLabel(a, b);
const plural = n => n + (n === 1 ? ' day' : ' days');

/* presets: a roving toolbar */
presetsEl.innerHTML = PRESETS.map((p, i) => '<button type="button" tabindex="-1" aria-pressed="false" data-i="' + i + '">' + p[0] + '</button>').join('');
const chips = [...presetsEl.children];

function monthHTML(k) {
  const first = firstOf(k), lead = P(first).w, label = fMonth.format(D(first)), mon = ((k % 12) + 12) % 12;
  let h = '<section class="mcl-range-month"><h4 class="mcl-range-mname" aria-hidden="true">' + label + '</h4>' +
    '<div class="mcl-range-grid" role="grid" aria-label="' + label + '"><div role="row" class="mcl-range-wd">' +
    WD.map(w => '<span role="columnheader" aria-label="' + w + '">' + w.slice(0, 2) + '</span>').join('') + '</div>';
  for (let r = 0; r < 6; r++) {
    h += '<div role="row" class="mcl-range-row">';
    for (let c = 0; c < 7; c++) {
      const n = first - lead + r * 7 + c, p = P(n);
      h += p.m !== mon ? '<span role="gridcell" class="mcl-range-pad"></span>'
        : '<button type="button" role="gridcell" class="mcl-range-day" tabindex="-1" data-dn="' + n +
          '" aria-label="' + fLong.format(D(n)) + '"><span>' + p.d + '</span></button>';
    }
    h += '</div>';
  }
  return h + '</div></section>';
}

function render(dir) {
  monthsEl.style.setProperty('--mcl-range-dir', RM.matches ? 0 : (dir || 0));
  monthsEl.innerHTML = monthHTML(view) + monthHTML(view + 1);
  cells = [...monthsEl.querySelectorAll('[data-dn]')];
  paint();
}

function curRange() {
  if (anchor != null) {
    let h = hover == null ? anchor : Math.min(hover, today);
    h = Math.max(Math.min(h, anchor + LIMIT - 1), anchor - LIMIT + 1);
    return [Math.min(anchor, h), Math.max(anchor, h), true];
  }
  return start == null ? null : [start, end, false];
}
const disabled = n => n > today || (anchor != null && Math.abs(n - anchor) >= LIMIT);

function paint() {
  const r = curRange(), lo = firstOf(view), hi = firstOf(view + shown());
  const want = Math.min(Math.max(focusDn, lo), hi - 1);
  let tab = null;
  for (const b of cells) {
    const n = +b.dataset.dn, inR = !!r && n >= r[0] && n <= r[1];
    b.toggleAttribute('data-in', inR);
    b.toggleAttribute('data-s', inR && n === r[0]);
    b.toggleAttribute('data-e', inR && n === r[1]);
    b.toggleAttribute('data-pv', inR && r[2]);
    b.toggleAttribute('data-anchor', n === anchor);
    b.toggleAttribute('data-today', n === today);
    const pp = inR ? P(n) : null;
    b.toggleAttribute('data-cl', inR && pp.d === 1 && n > r[0]);
    b.toggleAttribute('data-cr', inR && P(n + 1).d === 1 && n < r[1]);
    b.toggleAttribute('data-limit', anchor != null && n <= today && Math.abs(n - anchor) >= LIMIT);
    b.setAttribute('aria-selected', String(inR && !r[2]));
    if (disabled(n)) b.setAttribute('aria-disabled', 'true'); else b.removeAttribute('aria-disabled');
    b.tabIndex = -1;
    if (n === want) tab = b;
  }
  (tab || cells[0]).tabIndex = 0;
  summary(r);
}

function swap(el, html) {
  if (el.innerHTML === html) return;
  el.innerHTML = html;
  if (!RM.matches) el.animate([{ opacity: .2, filter: 'blur(3px)', transform: 'translateY(3px)' }, { opacity: 1, filter: 'blur(0)', transform: 'none' }],
    { duration: 260, easing: 'cubic-bezier(.2,.9,.25,1)' });
}

function summary(r) {
  swap(titleEl, r ? rangeLabel(r[0], r[1]) : 'No dates selected');
  swap(countEl, r ? plural(r[1] - r[0] + 1) : '0 days');
  root.toggleAttribute('data-empty', !r);
  root.toggleAttribute('data-picking', anchor != null);
  let pressed = -1;
  chips.forEach((b, i) => {
    const [a, z] = PRESETS[i][1](), on = anchor == null && start === a && end === z;
    b.setAttribute('aria-pressed', String(on));
    if (on) pressed = i;
  });
