  const dirty = anchor == null && start != null && (start !== applied[0] || end !== applied[1]);
  if (!busy) {
    const state = dirty ? 'ready' : (anchor == null && start != null ? 'done' : 'off');
    applyBtn.dataset.state = state;
    applyBtn.disabled = state !== 'ready';
    applyLbl.textContent = state === 'done' ? 'Applied' : 'Apply';
  }
