  if (tone) hintEl.dataset.tone = tone; else hintEl.removeAttribute('data-tone');
}
function hintRest() {
  if (start == null) return hint('Pick a start date, or choose a quick range.');
  const n = end - start + 1;
  hint('Compared with ' + shortLabel(start - n, start - 1) + ', the previous ' + plural(n) + '.');
}
function hintPick(n) {
  if (n != null && n > today) return hint('No data after today, ' + fShort.format(D(today)) + '.', 'warn');
  if (n != null && Math.abs(n - anchor) >= LIMIT) return hint('Ranges are capped at ' + LIMIT + ' days.', 'warn');
  hint('Pick an end date — up to ' + LIMIT + ' days. Esc cancels.');
}
function nudge() {
  if (!RM.matches) hintEl.animate([{ transform: 'translateX(0)' }, { transform: 'translateX(-4px)' }, { transform: 'translateX(4px)' }, { transform: 'translateX(-2px)' }, { transform: 'translateX(0)' }],
    { duration: 320, easing: 'cubic-bezier(.3,.7,.4,1)' });
}

function wave() {
  if (RM.matches || start == null) return;
  let i = 0;
  for (const b of cells) if (b.hasAttribute('data-in')) b.style.setProperty('--i', i++);
  monthsEl.classList.remove('is-wave'); void monthsEl.offsetWidth; monthsEl.classList.add('is-wave');
  clearTimeout(waveT);
  waveT = setTimeout(() => { if (root.isConnected) monthsEl.classList.remove('is-wave'); }, 1300);
