function showMonthOf(n, dir) {
  const lo = firstOf(view), hi = firstOf(view + shown());
  if (n >= lo && n < hi) { paint(); return; }
  const nv = n < lo ? monthKey(n) : viewFor(n);
  const d = dir == null ? Math.sign(nv - view) : dir;
  view = nv; render(d);
}

function select(n) {
  focusDn = n;
  if (n > today) { paint(); hintPick(n); nudge(); return; }
  if (anchor == null) {
    saved = start == null ? null : [start, end];
    anchor = hover = n; start = end = null;
    paint(); hintPick(); return;
  }
  if (Math.abs(n - anchor) >= LIMIT) { hintPick(n); nudge(); return; }
  start = Math.min(anchor, n); end = Math.max(anchor, n); anchor = hover = null; saved = null;
  paint(); wave(); hintRest();
}

function cancel() {
  if (anchor == null) return false;
  anchor = hover = null;
  if (saved) { start = saved[0]; end = saved[1]; }
  saved = null; paint(); hintRest();
  return true;
}

function go(t) {
  focusDn = t;
  if (anchor != null) { hover = t; hintPick(t); }
  showMonthOf(t);
  const c = cells.find(x => +x.dataset.dn === t);
