monthsEl.addEventListener('click', e => {
  const b = e.target.closest('[data-dn]');
  if (b) { select(+b.dataset.dn); b.focus({ preventScroll: true }); }
});
monthsEl.addEventListener('pointerover', e => {
  if (anchor == null) return;
  const b = e.target.closest('[data-dn]');
  if (!b || +b.dataset.dn === hover) return;
  hover = +b.dataset.dn; paint(); hintPick(hover);
});
monthsEl.addEventListener('keydown', e => {
  const b = e.target.closest('[data-dn]');
  if (!b) return;
  const n = +b.dataset.dn, p = P(n);
  let t;
  switch (e.key) {
    case 'ArrowLeft': t = n - 1; break;
    case 'ArrowRight': t = n + 1; break;
    case 'ArrowUp': t = n - 7; break;
    case 'ArrowDown': t = n + 7; break;
    case 'Home': t = n - p.w; break;
    case 'End': t = n + 6 - p.w; break;
    case 'PageUp': case 'PageDown': {
      const k = p.y * 12 + p.m + (e.key === 'PageUp' ? -1 : 1) * (e.shiftKey ? 12 : 1);
