});

presetsEl.addEventListener('click', e => {
  const b = e.target.closest('button[data-i]');
  if (!b) return;
  const [a, z] = PRESETS[+b.dataset.i][1]();
  start = a; end = z; anchor = hover = null; saved = null; focusDn = z;
  chips.forEach(c => { c.tabIndex = c === b ? 0 : -1; });
  const nv = viewForRange(a, z);
  if (nv !== view) { const d = Math.sign(nv - view); view = nv; render(d); } else paint();
