});
presetsEl.addEventListener('keydown', e => {
  const i = chips.indexOf(document.activeElement);
  if (i < 0) return;
  const j = e.key === 'ArrowRight' ? (i + 1) % chips.length : e.key === 'ArrowLeft' ? (i - 1 + chips.length) % chips.length
    : e.key === 'Home' ? 0 : e.key === 'End' ? chips.length - 1 : -1;
