prevBtn.addEventListener('click', () => { view--; render(-1); });
nextBtn.addEventListener('click', () => { view++; render(1); });

clearBtn.addEventListener('click', () => {
  start = end = anchor = hover = saved = null; paint();
  hint('Pick a start date, or choose a quick range.');
  const c = cells.find(x => x.tabIndex === 0); if (c) c.focus();
});

applyBtn.addEventListener('click', () => {
  if (busy || start == null || anchor != null) return;
  busy = true; applyBtn.dataset.state = 'busy'; applyBtn.disabled = true; applyLbl.textContent = 'Applying';
  hint('Refreshing 6 report widgets…');
  setTimeout(() => {
    if (!root.isConnected) return;
    busy = false; applied = [start, end]; paint();
    const n = end - start + 1;
    hint('Applied · compared with ' + shortLabel(start - n, start - 1) + '.', 'ok');
  }, 750);
});

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const s = shown();
  if (s !== lastShown) { lastShown = s; view = start != null ? viewForRange(start, end) : viewFor(focusDn); render(0); }
});
lastShown = shown();
view = viewForRange(start, end);
render(0);
hintRest();
ro.observe(root);

css:
@property --mcl-wheel-sun { syntax: '<number>'; inherits: true; initial-value: 0; }
@keyframes mcl-wheel-tilt {
  0%    { transform: translateY(-27px) scaleY(.36); opacity: .06; }
  16.7% { transform: translateY(-8px) scaleY(.7); opacity: .2; }
  33.3% { transform: translateY(-1px) scaleY(.93); opacity: .46; }
  50%   { transform: none; opacity: 1; }
  66.7% { transform: translateY(1px) scaleY(.93); opacity: .46; }
  83.3% { transform: translateY(8px) scaleY(.7); opacity: .2; }
  100%  { transform: translateY(27px) scaleY(.36); opacity: .06; }
}
@keyframes mcl-wheel-ring { 0%, 100% { rotate: 0deg; } 15% { rotate: 16deg; } 30% { rotate: -13deg; } 45% { rotate: 9deg; } 60% { rotate: -5deg; } 75% { rotate: 2deg; } }
@keyframes mcl-wheel-draw { from { stroke-dashoffset: 14; } }

.mcl-wheel {
  /* re-theme with these four */
  --mcl-wheel-bg: oklch(0.185 0.012 65);
  --mcl-wheel-ink: oklch(0.95 0.018 85);
  --mcl-wheel-accent: oklch(0.83 0.135 74);
  --mcl-wheel-warn: oklch(0.75 0.15 40);

  --mcl-wheel-mute: color-mix(in oklch, var(--mcl-wheel-ink) 55%, var(--mcl-wheel-bg));
  --mcl-wheel-faint: color-mix(in oklch, var(--mcl-wheel-ink) 30%, var(--mcl-wheel-bg));
  --mcl-wheel-line: color-mix(in oklch, var(--mcl-wheel-ink) 11%, transparent);
  --mcl-wheel-raise: color-mix(in oklch, var(--mcl-wheel-ink) 6%, transparent);
  --mcl-wheel-tint: color-mix(in oklch, var(--mcl-wheel-accent) 15%, transparent);
  --mcl-wheel-h: 40px;
  --mcl-wheel-out: cubic-bezier(.2, .9, .25, 1);
  --mcl-wheel-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);

  container-type: inline-size;
  position: relative; isolation: isolate; box-sizing: border-box; width: 100%;
  display: grid; gap: 12px;
  grid-template-areas: "head" "drum" "rel" "cycles" "foot";
  padding: 16px 16px 14px;
  border-radius: 20px; border: 1px solid var(--mcl-wheel-line);
  color: var(--mcl-wheel-ink);
  background:
    radial-gradient(120% 55% at 50% 118%, color-mix(in oklch, var(--mcl-wheel-accent) calc(var(--mcl-wheel-sun) * 26% + 5%), transparent), transparent 72%),
    var(--mcl-wheel-bg);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  transition: --mcl-wheel-sun 1.4s cubic-bezier(.3, .7, .3, 1);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; }
  & :focus-visible { outline: 2px solid var(--mcl-wheel-accent); outline-offset: 2px; }

  /* ---------- header ---------- */
  & .mcl-wheel-head { grid-area: head; display: flex; align-items: center; justify-content: space-between; gap: 12px; }
  & .mcl-wheel-title {
    margin: 0; display: flex; align-items: center; gap: 7px;
    font-size: 15px; font-weight: 650; letter-spacing: -.01em;
  }
  & .mcl-wheel-bell { width: 16px; height: 16px; color: var(--mcl-wheel-accent); transform-origin: 50% 12%; }
  & .mcl-wheel-bell.is-ring { animation: mcl-wheel-ring .9s var(--mcl-wheel-out); }
  & .mcl-wheel-sub { margin: 2px 0 0 23px; font-size: 11.5px; color: var(--mcl-wheel-mute); }
  & .mcl-wheel-switch {
    position: relative; flex: none; width: 42px; height: 25px; padding: 0; cursor: pointer;
    border: 0; border-radius: 99px; background: var(--mcl-wheel-faint);
    transition: background-color .25s;
    & i {
      position: absolute; top: 3px; left: 3px; width: 19px; height: 19px; border-radius: 50%;
      background: var(--mcl-wheel-ink); box-shadow: 0 1px 3px oklch(0 0 0 / .35);
      transition: translate .45s var(--mcl-wheel-spring);
    }
    &[aria-checked="true"] { background: var(--mcl-wheel-accent); & i { translate: 17px 0; background: var(--mcl-wheel-bg); } }
  }

  /* ---------- the drum ---------- */
  & .mcl-wheel-drum {
    grid-area: drum; position: relative;
    display: grid; justify-content: center; align-items: stretch;
    grid-template-columns: 70px 14px 70px 60px;
    grid-template-areas: "h sep m a";
    height: calc(var(--mcl-wheel-h) * 5);
    transition: opacity .3s;
  }
  & .mcl-wheel-band {
    position: absolute; inset-inline: 2px; top: 50%; height: var(--mcl-wheel-h); translate: 0 -50%;
    border-radius: 12px; background: var(--mcl-wheel-raise);
    box-shadow: inset 0 0 0 1px var(--mcl-wheel-line);
  }
  & .mcl-wheel-sep { grid-area: sep; align-self: center; text-align: center; font-size: 24px; font-weight: 500; color: var(--mcl-wheel-mute); translate: 0 -2px; }
  & .mcl-wheel-col {
    position: relative; height: 100%; overflow-y: scroll; overscroll-behavior: contain;
    scroll-snap-type: y mandatory; scrollbar-width: none; outline: none; cursor: ns-resize; touch-action: pan-y;
    mask-image: linear-gradient(transparent, #000 30%, #000 70%, transparent);
    &::-webkit-scrollbar { display: none; }
    & ol { list-style: none; margin: 0; padding: calc(var(--mcl-wheel-h) * 2) 0; }
    & li {
      height: var(--mcl-wheel-h); display: grid; place-items: center; scroll-snap-align: center;
      font-size: 25px; font-weight: 520; letter-spacing: -.01em; font-variant-numeric: tabular-nums;
      user-select: none; -webkit-user-select: none;
      transition: color .2s;
    }
    /* the snap target (li) stays untransformed; only its label rides the cylinder */
    & li > span { display: block; animation: mcl-wheel-tilt linear both; animation-timeline: view(); }
    & li.is-on { color: var(--mcl-wheel-accent); }
  }
  & [data-col="h"] { grid-area: h; & li { justify-items: end; padding-right: 8px; } }
  & [data-col="m"] { grid-area: m; & li { justify-items: start; padding-left: 8px; } }
  & [data-col="a"] { grid-area: a; & li { font-size: 14px; font-weight: 650; letter-spacing: .08em; } }
  /* one ring, moved to whichever drum has keyboard focus */
  & .mcl-wheel-ring {
    grid-row: 1; align-self: center; height: calc(var(--mcl-wheel-h) - 4px); pointer-events: none;
    border-radius: 10px; box-shadow: 0 0 0 2px var(--mcl-wheel-accent); opacity: 0; transition: opacity .15s;
  }
  & .mcl-wheel-drum:has([data-col="h"]:focus-visible) .mcl-wheel-ring { grid-area: h; opacity: 1; }
  & .mcl-wheel-drum:has([data-col="m"]:focus-visible) .mcl-wheel-ring { grid-area: m; opacity: 1; }
  & .mcl-wheel-drum:has([data-col="a"]:focus-visible) .mcl-wheel-ring { grid-area: a; opacity: 1; }

  /* ---------- readouts ---------- */
  & .mcl-wheel-rel {
    grid-area: rel; margin: 0; text-align: center; color: var(--mcl-wheel-mute); font-variant-numeric: tabular-nums;
    & b { color: var(--mcl-wheel-ink); font-weight: 620; }
  }
  & .mcl-wheel-cycles { grid-area: cycles; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
  & .mcl-wheel-chip {
    display: grid; justify-items: start; gap: 1px; padding: 7px 10px; cursor: pointer; text-align: left;
    border: 1px solid var(--mcl-wheel-line); border-radius: 12px; background: var(--mcl-wheel-raise);
    transition: background-color .2s, border-color .2s, scale .35s var(--mcl-wheel-spring);
    & b { font-size: 14px; font-weight: 620; font-variant-numeric: tabular-nums; letter-spacing: -.01em; white-space: nowrap; }
    & small { margin-left: 3px; font-size: 10px; font-weight: 650; letter-spacing: .04em; }
    & span { font-size: 10.5px; color: var(--mcl-wheel-mute); letter-spacing: .02em; white-space: nowrap; }
    & i { font-style: normal; }
    &:hover { border-color: color-mix(in oklch, var(--mcl-wheel-ink) 22%, transparent); }
    &:active { scale: .96; }
    &[aria-pressed="true"] { border-color: var(--mcl-wheel-accent); background: var(--mcl-wheel-tint); & b { color: var(--mcl-wheel-accent); } }
  }

  /* ---------- footer ---------- */
  & .mcl-wheel-foot {
    grid-area: foot; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 12px;
    padding-top: 12px; border-top: 1px solid var(--mcl-wheel-line);
  }
  & .mcl-wheel-note {
    margin: 0; font-size: 11.5px; line-height: 1.35; color: var(--mcl-wheel-mute); text-wrap: pretty;
    &[data-tone="warn"] { color: var(--mcl-wheel-warn); }
  }
  & .mcl-wheel-save {
    height: 34px; padding: 0 14px; border: 0; border-radius: 11px; cursor: pointer; white-space: nowrap;
    display: inline-flex; align-items: center; gap: 6px;
    background: var(--mcl-wheel-accent); color: var(--mcl-wheel-bg); font-size: 13px; font-weight: 650;
    transition: background-color .2s, color .2s, scale .35s var(--mcl-wheel-spring);
    & svg { width: 15px; height: 15px; stroke-width: 2; display: none; stroke-dasharray: 14; }
    &:active:not(:disabled) { scale: .95; }
    &:disabled { cursor: default; background: var(--mcl-wheel-tint); color: var(--mcl-wheel-accent); & svg { display: block; animation: mcl-wheel-draw .45s var(--mcl-wheel-out) backwards; } }
  }

  &[data-off] {
    & .mcl-wheel-drum { opacity: .42; }
    & .mcl-wheel-col li.is-on { color: inherit; }
    & .mcl-wheel-bell { color: var(--mcl-wheel-faint); }
  }

  @container (max-width: 290px) {
    & .mcl-wheel-drum { grid-template-columns: 58px 12px 58px 52px; }
    & .mcl-wheel-col li { font-size: 22px; }
    & .mcl-wheel-chip { padding: 6px 8px; & b { font-size: 12.5px; } & i { display: none; } }
    & .mcl-wheel-foot { grid-template-columns: 1fr; }
  }
}

@supports not (animation-timeline: view()) {
  .mcl-wheel .mcl-wheel-col li > span { animation: none; }
  .mcl-wheel .mcl-wheel-col li { opacity: .3; transition: opacity .2s, color .2s; }
  .mcl-wheel .mcl-wheel-col li.is-on { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .mcl-wheel {
    transition: none;
    & .mcl-wheel-col li > span { animation: none; }
    & .mcl-wheel-col li { opacity: .32; }
    & .mcl-wheel-col li.is-on { opacity: 1; }
    & .mcl-wheel-switch i, & .mcl-wheel-chip, & .mcl-wheel-save { transition: background-color .2s, color .2s; }
    & .mcl-wheel-bell.is-ring, & .mcl-wheel-save svg { animation: none !important; }
  }
}

