@property --mcl-heat-fl { syntax: '<length>'; inherits: false; initial-value: 0px; }
@property --mcl-heat-fr { syntax: '<length>'; inherits: false; initial-value: 0px; }
@keyframes mcl-heat-edges { from { --mcl-heat-fl: 0px; --mcl-heat-fr: 18px; } to { --mcl-heat-fl: 18px; --mcl-heat-fr: 0px; } }

.mcl-heat {
  /* re-theme with these four */
  --mcl-heat-paper: oklch(0.975 0.01 85);
  --mcl-heat-ink: oklch(0.25 0.03 262);
  --mcl-heat-accent: oklch(0.5 0.19 263);
  --mcl-heat-mark: oklch(0.63 0.19 36);

  --mcl-heat-mute: color-mix(in oklch, var(--mcl-heat-ink) 56%, var(--mcl-heat-paper));
  /* tints mix toward transparent, not toward the cream: an oklch mix with a tinted
     paper would swing the hue the short way round, through green */
  --mcl-heat-line: color-mix(in oklch, var(--mcl-heat-ink) 12%, transparent);
  --mcl-heat-l0: color-mix(in oklch, var(--mcl-heat-ink) 7%, transparent);
  --mcl-heat-l1: color-mix(in oklch, var(--mcl-heat-accent) 22%, transparent);
  --mcl-heat-l2: color-mix(in oklch, var(--mcl-heat-accent) 45%, transparent);
  --mcl-heat-l3: color-mix(in oklch, var(--mcl-heat-accent) 72%, transparent);
  --mcl-heat-l4: color-mix(in oklch, var(--mcl-heat-accent) 82%, var(--mcl-heat-ink));
  --mcl-heat-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mcl-heat-out: cubic-bezier(.2, .9, .25, 1);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%;
  display: grid; gap: 12px;
  grid-template-areas: "head" "stats" "grid" "key" "detail";
  padding: 16px;
  border: 1px solid var(--mcl-heat-line); border-radius: 16px;
  background: var(--mcl-heat-paper); color: var(--mcl-heat-ink);
  box-shadow: 0 16px 34px -26px color-mix(in oklch, var(--mcl-heat-ink) 45%, transparent);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; }
  & :focus-visible { outline: 2px solid var(--mcl-heat-ink); outline-offset: 2px; }

  & .mcl-heat-head { grid-area: head; display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
  & .mcl-heat-title { margin: 0; font-size: 15px; font-weight: 700; letter-spacing: -.012em; text-wrap: balance; }
  & .mcl-heat-sub { margin: 2px 0 0; font-size: 11.5px; color: var(--mcl-heat-mute); text-wrap: pretty; }
  & .mcl-heat-seg {
    flex: none; display: flex; padding: 2px; border-radius: 9px; background: var(--mcl-heat-l0);
    & button {
      height: 24px; padding: 0 9px; border: 0; border-radius: 7px; background: none; cursor: pointer;
      font-size: 11.5px; font-weight: 600; color: var(--mcl-heat-mute);
      transition: background-color .2s, color .2s, box-shadow .2s;
    }
    & [aria-checked="true"] { background: var(--mcl-heat-paper); color: var(--mcl-heat-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--mcl-heat-ink) 18%, transparent); }
  }

  /* ---------- stats ---------- */
  & .mcl-heat-stats {
    grid-area: stats; margin: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px;
    border-radius: 11px; overflow: hidden; background: var(--mcl-heat-line); border: 1px solid var(--mcl-heat-line);
    & div { padding: 7px 8px 8px; background: var(--mcl-heat-paper); min-width: 0; }
    & dt { font-size: 9px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--mcl-heat-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & dd { margin: 2px 0 0; font-size: 10.5px; color: var(--mcl-heat-mute); white-space: nowrap; font-variant-numeric: tabular-nums; }
    & b { font-size: clamp(14px, 4.8cqi, 18px); font-weight: 700; letter-spacing: -.02em; color: var(--mcl-heat-ink); }
  }

  /* ---------- the grid ---------- */
  & .mcl-heat-scroll {
    grid-area: grid; overflow-x: auto; scrollbar-width: none; margin-inline: -4px; padding: 4px;
    overscroll-behavior-x: contain;
    &::-webkit-scrollbar { display: none; }
  }
  & .mcl-heat-grid {
    --mcl-heat-c: clamp(8px, calc((100cqi - 28px) / 26 - 2.5px), 15px);
    display: grid; gap: 2.5px; width: max-content;
    grid-template-columns: 20px repeat(26, var(--mcl-heat-c));
  }
  & .mcl-heat-months, & .mcl-heat-row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
  & .mcl-heat-months span { font-size: 10px; font-weight: 600; color: var(--mcl-heat-mute); white-space: nowrap; height: 14px; line-height: 14px; }
  /* weekday labels stay put while the weeks scroll under them */
  & .mcl-heat-row > span {
    position: sticky; left: -4px; z-index: 3; margin-left: -4px; padding-left: 4px;
    font-size: 9px; color: var(--mcl-heat-mute); line-height: var(--mcl-heat-c); height: var(--mcl-heat-c);
    background: var(--mcl-heat-paper); box-shadow: 3px 0 0 var(--mcl-heat-paper);
  }
  & .mcl-heat-cell {
    position: relative; width: var(--mcl-heat-c); aspect-ratio: 1; padding: 0; border: 0; border-radius: 2.5px; cursor: pointer;
    background: var(--mcl-heat-l0);
    transition: background-color .4s var(--mcl-heat-out), opacity .25s, scale .35s var(--mcl-heat-spring);
    @starting-style { opacity: 0; scale: .2; }
    &[data-l="1"] { background: var(--mcl-heat-l1); }
    &[data-l="2"] { background: var(--mcl-heat-l2); }
    &[data-l="3"] { background: var(--mcl-heat-l3); }
    &[data-l="4"] { background: var(--mcl-heat-l4); }
    &[aria-disabled="true"] { background: none; box-shadow: inset 0 0 0 1px var(--mcl-heat-line); cursor: default; }
    &[data-mark]::after { content: ""; position: absolute; inset: -2.5px; border-radius: 4px; border: 1.5px solid var(--mcl-heat-mark); }
    &:hover:not([aria-disabled="true"]) { scale: 1.3; z-index: 1; }
    &[aria-selected="true"] { box-shadow: 0 0 0 1.5px var(--mcl-heat-paper), 0 0 0 3px var(--mcl-heat-ink); z-index: 1; }
    &:focus-visible { outline: 2px solid var(--mcl-heat-ink); outline-offset: 1px; z-index: 2; }
  }
  & .mcl-heat-grid.is-wave .mcl-heat-cell { transition-delay: calc(var(--c) * 16ms); }

  /* legend: hover a swatch to isolate a level (pure :has), click to pin it */
  & .mcl-heat-key {
    grid-area: key; display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
    font-size: 11px; color: var(--mcl-heat-mute);
  }
  & .mcl-heat-swatches { display: inline-flex; gap: 3px; }
  & .mcl-heat-swatches button {
    width: 13px; height: 13px; padding: 0; border: 0; border-radius: 3px; cursor: pointer; background: var(--mcl-heat-l0);
    transition: scale .3s var(--mcl-heat-spring), box-shadow .2s;
    &[data-l="1"] { background: var(--mcl-heat-l1); }
    &[data-l="2"] { background: var(--mcl-heat-l2); }
    &[data-l="3"] { background: var(--mcl-heat-l3); }
    &[data-l="4"] { background: var(--mcl-heat-l4); }
    &:hover { scale: 1.2; }
    &[aria-pressed="true"] { box-shadow: 0 0 0 1.5px var(--mcl-heat-paper), 0 0 0 3px var(--mcl-heat-ink); }
  }
  & .mcl-heat-markkey {
    margin-left: auto; display: inline-flex; align-items: center; gap: 6px;
    & i { width: 11px; height: 11px; border-radius: 3px; border: 1.5px solid var(--mcl-heat-mark); }
  }
  &:has(.mcl-heat-swatches [data-l="0"]:is(:hover, :focus-visible)) .mcl-heat-cell:not([data-l="0"]),
  &:has(.mcl-heat-swatches [data-l="1"]:is(:hover, :focus-visible)) .mcl-heat-cell:not([data-l="1"]),
  &:has(.mcl-heat-swatches [data-l="2"]:is(:hover, :focus-visible)) .mcl-heat-cell:not([data-l="2"]),
  &:has(.mcl-heat-swatches [data-l="3"]:is(:hover, :focus-visible)) .mcl-heat-cell:not([data-l="3"]),
  &:has(.mcl-heat-swatches [data-l="4"]:is(:hover, :focus-visible)) .mcl-heat-cell:not([data-l="4"]),
  &[data-filter="0"] .mcl-heat-cell:not([data-l="0"]), &[data-filter="1"] .mcl-heat-cell:not([data-l="1"]),
  &[data-filter="2"] .mcl-heat-cell:not([data-l="2"]), &[data-filter="3"] .mcl-heat-cell:not([data-l="3"]),
  &[data-filter="4"] .mcl-heat-cell:not([data-l="4"]) { opacity: .16; }

  & .mcl-heat-detail {
    grid-area: detail; margin: 0; padding-top: 10px; border-top: 1px solid var(--mcl-heat-line);
    font-size: 12px; color: var(--mcl-heat-mute); text-wrap: pretty; font-variant-numeric: tabular-nums;
    & b { color: var(--mcl-heat-ink); font-weight: 650; }
    & em { font-style: normal; color: var(--mcl-heat-mark); font-weight: 600; }
  }

  /* tooltip glides between cells */
  & .mcl-heat-tip {
    position: absolute; left: 0; top: 0; z-index: 5; pointer-events: none;
    display: grid; gap: 1px; padding: 6px 9px; border-radius: 8px; white-space: nowrap;
    background: var(--mcl-heat-ink); color: var(--mcl-heat-paper);
    font-size: 11px; font-variant-numeric: tabular-nums;
    box-shadow: 0 8px 20px -8px color-mix(in oklch, var(--mcl-heat-ink) 60%, transparent);
    opacity: 0; scale: .92; transform-origin: 50% 100%;
    transition: opacity .15s, scale .25s var(--mcl-heat-out), translate .22s var(--mcl-heat-out);
    & b { font-size: 12px; font-weight: 650; }
    & span { opacity: .72; }
    &.is-on { opacity: 1; scale: 1; }
  }

  @container (max-width: 290px) {
    & .mcl-heat-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    & .mcl-heat-head { flex-wrap: wrap; }
  }
}

@supports (animation-timeline: scroll()) {
  .mcl-heat .mcl-heat-scroll {
    /* the weekday column stays solid; the weeks fade in from under it as you scroll */
    mask-image: linear-gradient(90deg, #000 27px, transparent 27px, #000 calc(27px + var(--mcl-heat-fl)), #000 calc(100% - var(--mcl-heat-fr)), transparent);
    animation: mcl-heat-edges linear both;
    animation-timeline: scroll(self inline);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mcl-heat {
    & .mcl-heat-cell { transition: background-color .2s, opacity .2s; @starting-style { opacity: 0; scale: 1; } }
    & .mcl-heat-cell:hover:not([aria-disabled="true"]) { scale: 1; }
    & .mcl-heat-grid.is-wave .mcl-heat-cell { transition-delay: 0ms; }
    & .mcl-heat-tip { transition: opacity .15s; scale: 1; }
    & .mcl-heat-swatches button { transition: box-shadow .2s; }
  }
}

