const $ = s => root.querySelector(s);
const DAY = 864e5, WEEKS = 26;
const U = (y, m, d) => Date.UTC(y, m, d) / DAY;
const START = U(2026, 3, 6), LAST = U(2026, 9, 2), RECITAL = U(2026, 8, 19);
const BREAK = [U(2026, 6, 13), U(2026, 6, 21)];
const F = o => new Intl.DateTimeFormat('en-US', Object.assign({ timeZone: 'UTC' }, o));
const fDay = F({ weekday: 'short', month: 'short', day: 'numeric' }), fLong = F({ weekday: 'long', month: 'long', day: 'numeric' });
const fMon = F({ month: 'short' });
const D = n => new Date(n * DAY);
const WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

/* deterministic practice log (mulberry32) — every number on screen is derived from it */
let seed = 20260406;
const rnd = () => { seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const piece = n => n < U(2026, 5, 1) ? 'Bach, Suite No. 3 — Bourrées' : n < U(2026, 7, 1) ? 'Fauré, Élégie' : n < RECITAL ? 'Elgar, Concerto — I. Adagio' : n === RECITAL ? 'Recital, Hollis Hall' : 'Scales and sight-reading';
const days = [];
for (let i = 0; i < WEEKS * 7; i++) {
  const n = START + i, w = i % 7;
  if (n > LAST) { days.push({ n, w, i, future: true, min: 0, ses: 0 }); continue; }
  const ramp = n >= RECITAL - 18 && n < RECITAL;
  const p = ramp ? .97 : w === 6 ? .55 : w === 5 ? .85 : .8;
  let min = 0;
  if (n >= BREAK[0] && n <= BREAK[1]) min = 0;
  else if (n === RECITAL) min = 150;
  else if (n > RECITAL && n <= RECITAL + 2) min = 0;
  else if (rnd() < p) min = Math.round((w >= 5 ? 35 + rnd() * 55 : 18 + rnd() * 40) + (ramp ? 22 + rnd() * 20 : 0));
  const ses = !min ? 0 : n === RECITAL ? 3 : Math.min(4, 1 + (min >= 30) + (min >= 70) + (rnd() < .15));
  days.push({ n, w, i, future: false, min, ses });
}
const logged = days.filter(d => !d.future);

/* stats, from the same records */
const totalMin = logged.reduce((a, d) => a + d.min, 0), totalSes = logged.reduce((a, d) => a + d.ses, 0);
const active = logged.filter(d => d.min > 0).length;
let longest = 0, run = 0;
for (const d of logged) { run = d.min ? run + 1 : 0; longest = Math.max(longest, run); }
let current = 0;
for (let k = logged.length - 1; k >= 0 && logged[k].min; k--) current++;

const MEASURE = {
  min: { lv: v => !v ? 0 : v < 30 ? 1 : v < 50 ? 2 : v < 75 ? 3 : 4, key: ['No practice', 'Under 30 min', '30 to 49 min', '50 to 74 min', '75 min or more'] },
  ses: { lv: v => Math.min(v, 4), key: ['No sessions', '1 session', '2 sessions', '3 sessions', '4 sessions'] }
};
let measure = 'min', sel = logged[logged.length - 1].n, filter = null;

const grid = $('[data-grid]'), tip = $('[data-tip]'), detail = $('[data-detail]'), stats = $('[data-stats]');
const swatches = $('[data-swatches]'), scroller = $('[data-scroll]'), seg = $('[data-seg]');
const say = d => d.future ? 'not logged yet' : d.min ? d.min + ' minutes, ' + d.ses + (d.ses === 1 ? ' session' : ' sessions') : 'no practice';

/* months row + seven weekday rows that share the grid's tracks through subgrid */
let h = '<div class="mcl-heat-months" aria-hidden="true">';
let lastM = -1;
for (let c = 0; c < WEEKS; c++) {
  const m = D(START + c * 7).getUTCMonth();
  if (m !== lastM && c < WEEKS - 1) h += '<span style="grid-column:' + (c + 2) + ' / span 3">' + fMon.format(D(START + c * 7)) + '</span>';
  lastM = m;
}
h += '</div>';
for (let w = 0; w < 7; w++) {
  h += '<div class="mcl-heat-row" role="row"><span role="rowheader" aria-label="' + WD[w] + '">' + (w % 2 === 0 && w < 6 ? WD[w].slice(0, 3) : '') + '</span>';
  for (let c = 0; c < WEEKS; c++) {
    const d = days[c * 7 + w];
    h += '<button type="button" role="gridcell" class="mcl-heat-cell" tabindex="-1" style="--c:' + c + '" data-n="' + d.n + '"' +
      (d.future ? ' aria-disabled="true"' : '') + (d.n === RECITAL ? ' data-mark' : '') +
      ' aria-label="' + fLong.format(D(d.n)) + ': ' + say(d) + '"></button>';
  }
  h += '</div>';
}
grid.classList.add('is-wave');
grid.innerHTML = h;
const cells = [...grid.querySelectorAll('.mcl-heat-cell')];
const byN = new Map(cells.map(c => [+c.dataset.n, c]));
const rec = n => days[n - START];
setTimeout(() => { if (root.isConnected) grid.classList.remove('is-wave'); }, 900);

function paint() {
  const M = MEASURE[measure];
  for (const c of cells) { const d = rec(+c.dataset.n); c.dataset.l = d.future ? 0 : M.lv(measure === 'min' ? d.min : d.ses); }
  swatches.innerHTML = M.key.map((k, i) => '<button type="button" data-l="' + i + '" aria-label="' + k + '" title="' + k + '" aria-pressed="' + (filter === i) + '"></button>').join('');
  const hrs = (totalMin / 60).toFixed(1);
  stats.innerHTML = [
    measure === 'min' ? ['Practised', '<b>' + hrs + '</b> h'] : ['Sessions', '<b>' + totalSes + '</b>'],
    ['Active', '<b>' + active + '</b>/' + logged.length],
    ['Longest', '<b>' + longest + '</b> d'],
    ['Current', '<b>' + current + '</b> d']
  ].map(s => '<div><dt>' + s[0] + '</dt><dd>' + s[1] + '</dd></div>').join('');
}

function select(n, focus) {
  const d = rec(n);
  if (!d) return;
  sel = n;
  for (const c of cells) { c.setAttribute('aria-selected', String(+c.dataset.n === n)); c.tabIndex = +c.dataset.n === n ? 0 : -1; }
  const c = byN.get(n);
  if (focus) c.focus();
  detail.innerHTML = d.future ? '<b>' + fDay.format(D(n)) + '</b> — not logged yet.'
    : !d.min ? '<b>' + fDay.format(D(n)) + '</b> — ' + (n >= BREAK[0] && n <= BREAK[1] ? 'tour break, Porto.' : 'rest day.')
    : '<b>' + fDay.format(D(n)) + '</b> — ' + d.min + ' min in ' + d.ses + (d.ses === 1 ? ' session' : ' sessions') + ' · ' +
      (n === RECITAL ? '<em>' + piece(n) + '</em>' : piece(n));
}

function showTip(c) {
  const d = rec(+c.dataset.n);
  tip.firstElementChild.textContent = d.future ? 'Not logged yet' : d.min ? d.min + ' min · ' + d.ses + (d.ses === 1 ? ' session' : ' sessions') : 'No practice';
  tip.lastElementChild.textContent = fDay.format(D(d.n)) + (d.n === RECITAL ? ' · Recital' : '');
  const a = c.getBoundingClientRect(), r = root.getBoundingClientRect();
  const tw = tip.offsetWidth, th = tip.offsetHeight;
  const x = Math.max(6, Math.min(r.width - tw - 6, a.left - r.left + a.width / 2 - tw / 2));
  const y = a.top - r.top - th - 8;
  const first = !tip.classList.contains('is-on');
  if (first) { tip.style.transition = 'none'; tip.style.translate = x + 'px ' + y + 'px'; void tip.offsetWidth; tip.style.transition = ''; }
  else tip.style.translate = x + 'px ' + y + 'px';
  tip.classList.add('is-on');
}
const hideTip = () => tip.classList.remove('is-on');

grid.addEventListener('pointerover', e => { const c = e.target.closest('.mcl-heat-cell'); if (c) showTip(c); });
grid.addEventListener('pointerleave', () => { if (!grid.contains(document.activeElement)) hideTip(); });
grid.addEventListener('focusin', e => { const c = e.target.closest('.mcl-heat-cell'); if (c) showTip(c); });
grid.addEventListener('focusout', e => { if (!grid.contains(e.relatedTarget)) hideTip(); });
grid.addEventListener('click', e => { const c = e.target.closest('.mcl-heat-cell'); if (c) select(+c.dataset.n, true); });
grid.addEventListener('keydown', e => {
  const c = e.target.closest('.mcl-heat-cell');
  if (!c) return;
  const n = +c.dataset.n, i = n - START, w = i % 7;
  let t = null;
  switch (e.key) {
    case 'ArrowLeft': t = n - 7; break;
    case 'ArrowRight': t = n + 7; break;
    case 'ArrowUp': t = w > 0 ? n - 1 : null; break;
    case 'ArrowDown': t = w < 6 ? n + 1 : null; break;
    case 'Home': t = START + w; break;
    case 'End': t = START + (WEEKS - 1) * 7 + w; break;
    case 'PageUp': t = n - 28; break;
    case 'PageDown': t = n + 28; break;
    case 'Enter': case ' ': e.preventDefault(); select(n, true); return;
    default: return;
  }
  e.preventDefault();
  if (t == null || !byN.has(t)) return;
  const nc = byN.get(t);
  for (const x of cells) x.tabIndex = -1;
  nc.tabIndex = 0; nc.focus(); nc.scrollIntoView({ block: 'nearest', inline: 'nearest' });
});

swatches.addEventListener('click', e => {
  const b = e.target.closest('button');
  if (!b) return;
  const l = +b.dataset.l;
  filter = filter === l ? null : l;
  if (filter == null) root.removeAttribute('data-filter'); else root.dataset.filter = filter;
  swatches.querySelectorAll('button').forEach(x => x.setAttribute('aria-pressed', String(+x.dataset.l === filter)));
});

function setMeasure(m, focus) {
  if (m === measure) return;
  measure = m;
  seg.querySelectorAll('[role="radio"]').forEach(b => { const on = b.dataset.m === m; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  grid.classList.add('is-wave');
  paint();
  clearTimeout(setMeasure.t);
  setMeasure.t = setTimeout(() => { if (root.isConnected) grid.classList.remove('is-wave'); }, 1000);
}
seg.addEventListener('click', e => { const b = e.target.closest('[data-m]'); if (b) setMeasure(b.dataset.m); });
seg.addEventListener('keydown', e => {
  if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
  e.preventDefault();
  setMeasure(measure === 'min' ? 'ses' : 'min', true);
});

paint();
select(sel, false);
scroller.scrollLeft = scroller.scrollWidth;

css:
@keyframes mcl-zones-in { from { opacity: 0; transform: translateY(4px); } }
@keyframes mcl-zones-pulse { 0% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--mcl-zones-accent) 55%, transparent); } 100% { box-shadow: 0 0 0 10px transparent; } }
@keyframes mcl-zones-spin { to { rotate: 1turn; } }

.mcl-zones {
  /* re-theme with these four */
  --mcl-zones-bg: oklch(0.205 0.008 85);
  --mcl-zones-ink: oklch(0.95 0.012 95);
  --mcl-zones-accent: oklch(0.88 0.17 124);
  --mcl-zones-edge: oklch(0.8 0.13 72);

  --mcl-zones-mute: color-mix(in oklch, var(--mcl-zones-ink) 56%, var(--mcl-zones-bg));
  --mcl-zones-faint: color-mix(in oklch, var(--mcl-zones-ink) 32%, var(--mcl-zones-bg));
  --mcl-zones-line: color-mix(in oklch, var(--mcl-zones-ink) 11%, transparent);
  --mcl-zones-raise: color-mix(in oklch, var(--mcl-zones-ink) 5%, transparent);
  --mcl-zones-work: color-mix(in oklch, var(--mcl-zones-accent) 62%, transparent);
  --mcl-zones-early: color-mix(in oklch, var(--mcl-zones-edge) 38%, transparent);
  --mcl-zones-night: color-mix(in oklch, var(--mcl-zones-ink) 6%, transparent);
  --mcl-zones-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);
  --mcl-zones-out: cubic-bezier(.2, .9, .25, 1);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%;
  display: grid; gap: 12px; grid-template-areas: "head" "board" "foot";
  padding: 16px;
  border: 1px solid var(--mcl-zones-line); border-radius: 18px;
  background: linear-gradient(180deg, color-mix(in oklch, var(--mcl-zones-ink) 3%, transparent), transparent 40%), var(--mcl-zones-bg);
  color: var(--mcl-zones-ink);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; }
  & :focus-visible { outline: 2px solid var(--mcl-zones-accent); outline-offset: 2px; }

  /* ---------- header ---------- */
  & .mcl-zones-head {
    grid-area: head; display: grid; align-items: center; column-gap: 10px;
    grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "eyebrow date" "title title";
  }
  & .mcl-zones-titles { display: contents; }
  & .mcl-zones-title { grid-area: title; }
  & .mcl-zones-eyebrow { grid-area: eyebrow; margin: 0 0 2px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--mcl-zones-accent); }
  & .mcl-zones-title { margin: 0; font-size: 15px; font-weight: 650; letter-spacing: -.01em; text-wrap: balance; }
  & .mcl-zones-date {
    grid-area: date; justify-self: end;
    display: inline-flex; align-items: center; gap: 2px; padding: 2px; border-radius: 10px; background: var(--mcl-zones-raise);
    & span { min-width: 76px; text-align: center; font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; }
    & button { width: 26px; height: 26px; padding: 0; border: 0; border-radius: 8px; background: none; cursor: pointer; display: grid; place-items: center; transition: background-color .15s; }
    & button:hover { background: var(--mcl-zones-line); }
    & svg { width: 14px; height: 14px; }
  }

  /* ---------- board: one column set shared by every row (subgrid) ---------- */
  & .mcl-zones-board {
    grid-area: board; position: relative; display: grid; column-gap: 10px;
    grid-template-columns: 28px minmax(0, 1fr) auto;
    grid-template-rows: auto auto repeat(4, auto);
    padding-top: 22px; /* room for the time flag above the window */
  }
  & .mcl-zones-fit, & .mcl-zones-axis { grid-column: 2; }
  & .mcl-zones-fit {
    grid-row: 1; height: 26px; display: grid; grid-template-columns: repeat(48, minmax(0, 1fr)); align-items: end; gap: 1px;
    & i {
      height: calc(var(--s) / 8 * 100% + 2px); border-radius: 1.5px 1.5px 0 0;
      background: var(--mcl-zones-faint); opacity: .55; transform-origin: bottom;
      transition: height .5s var(--mcl-zones-spring), background-color .3s, opacity .3s;
      transition-delay: calc(var(--i) * 6ms);
    }
    & i[data-q="7"], & i[data-q="8"] { background: var(--mcl-zones-accent); opacity: 1; }
    & i[data-q="6"] { background: color-mix(in oklch, var(--mcl-zones-accent) 55%, var(--mcl-zones-bg)); opacity: 1; }
  }
  & .mcl-zones-axis {
    grid-row: 2; display: flex; justify-content: space-between; margin: 4px 0 8px;
    font: 500 9.5px/1 ui-monospace, Menlo, monospace; color: var(--mcl-zones-mute); letter-spacing: .02em;
    & span { width: 0; display: flex; justify-content: center; white-space: nowrap; }
  }
  & .mcl-zones-row {
    grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center;
    grid-template-rows: auto auto; row-gap: 3px; padding: 5px 0; border-top: 1px solid var(--mcl-zones-line);
    animation: mcl-zones-in .4s var(--mcl-zones-out) backwards; animation-delay: calc(var(--i) * 50ms);
  }
  & .mcl-zones-av {
    grid-row: 1 / span 2; width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center;
    font-size: 10.5px; font-weight: 700; letter-spacing: .02em;
    background: oklch(0.42 0.07 var(--h)); color: oklch(0.95 0.03 var(--h));
  }
  & .mcl-zones-who { grid-column: 2; margin: 0; font-size: 11.5px; color: var(--mcl-zones-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    & b { color: var(--mcl-zones-ink); font-weight: 600; }
    & em { font-style: normal; margin-left: 4px; padding: 0 5px; border-radius: 4px; font-size: 9.5px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; background: var(--mcl-zones-line); color: var(--mcl-zones-ink); }
  }
  & .mcl-zones-strip {
    grid-column: 2; height: 12px; border-radius: 4px;
    background-image: var(--g);
    box-shadow: inset 0 0 0 1px var(--mcl-zones-line);
    transition: opacity .25s;
  }
  & .mcl-zones-local {
    grid-column: 3; grid-row: 1 / span 2; justify-self: end; text-align: right; min-width: 64px;
    font-variant-numeric: tabular-nums;
    & b { display: flex; align-items: center; justify-content: flex-end; gap: 4px; font-size: 13px; font-weight: 650; }
    & svg { width: 13px; height: 13px; }
    & small { display: block; font-size: 10.5px; color: var(--mcl-zones-mute); }
    &[data-st="2"] svg { color: var(--mcl-zones-accent); }
    &[data-st="1"] b { color: var(--mcl-zones-edge); }
    &[data-st="0"] b, &[data-st="-1"] b { color: var(--mcl-zones-faint); }
  }

  /* the 45-minute window: one element spanning every row, positioned in track-relative cqi */
  & .mcl-zones-track {
    grid-column: 2; grid-row: 1 / -1; position: relative; z-index: 2; container-type: inline-size;
    cursor: ew-resize; touch-action: none; border-radius: 6px; outline-offset: 4px;
  }
  & .mcl-zones-win {
    --t: 0;
    position: absolute; top: -4px; bottom: 2px; left: 0; width: calc(45 / 1440 * 100cqi); min-width: 5px;
    translate: calc(var(--t) / 1440 * 100cqi) 0;
    border-radius: 4px;
    background: color-mix(in oklch, var(--mcl-zones-ink) 16%, transparent);
    box-shadow: 0 0 0 1.5px var(--mcl-zones-ink), 0 0 18px color-mix(in oklch, var(--mcl-zones-ink) 22%, transparent);
    transition: translate .45s var(--mcl-zones-spring);
    pointer-events: none;
    & b {
      position: absolute; bottom: 100%; left: 50%; translate: -50% -4px; white-space: nowrap;
      padding: 2px 6px; border-radius: 5px; background: var(--mcl-zones-ink); color: var(--mcl-zones-bg);
      font: 650 10px/1.3 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
    }
  }
  & .mcl-zones-track.is-drag .mcl-zones-win { transition: none; }
  & .mcl-zones-win.is-best { animation: mcl-zones-pulse .7s ease-out; }
  & .mcl-zones-empty {
    position: absolute; inset: 0; margin: 0; display: grid; place-content: center; justify-items: center; gap: 8px;
    text-align: center; font-size: 12px; color: var(--mcl-zones-mute); border-radius: 8px;
    background: color-mix(in oklch, var(--mcl-zones-bg) 82%, transparent); backdrop-filter: blur(2px);
    & button { height: 28px; padding: 0 12px; border: 1px solid var(--mcl-zones-line); border-radius: 8px; background: var(--mcl-zones-raise); cursor: pointer; font-size: 12px; font-weight: 600; }
    &[hidden] { display: none; }
  }
  &:has(.mcl-zones-empty:not([hidden])) .mcl-zones-win { opacity: 0; }

  /* ---------- footer ---------- */
  & .mcl-zones-foot {
    grid-area: foot; display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 8px;
    padding-top: 12px; border-top: 1px solid var(--mcl-zones-line);
  }
  & .mcl-zones-sum { margin: 0; font-size: 12px; color: var(--mcl-zones-mute); text-wrap: pretty; font-variant-numeric: tabular-nums;
    & b { color: var(--mcl-zones-ink); font-weight: 650; }
  }
  & .mcl-zones-best, & .mcl-zones-hold {
    height: 32px; padding: 0 12px; border-radius: 10px; cursor: pointer; white-space: nowrap;
    display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 650;
    transition: background-color .2s, color .2s, scale .3s var(--mcl-zones-spring);
    &:active:not(:disabled) { scale: .95; }
    & svg { width: 14px; height: 14px; }
  }
  & .mcl-zones-best { border: 1px solid var(--mcl-zones-line); background: none; &:hover { background: var(--mcl-zones-raise); } }
  & .mcl-zones-hold {
    border: 0; background: var(--mcl-zones-accent); color: oklch(0.2 0.03 124);
    &[data-state="busy"] span::before { content: ""; display: inline-block; width: 11px; height: 11px; margin-right: 6px; vertical-align: -1px; border-radius: 50%; border: 2px solid currentColor; border-right-color: transparent; animation: mcl-zones-spin .7s linear infinite; }
    &[data-state="held"] { background: color-mix(in oklch, var(--mcl-zones-accent) 16%, transparent); color: var(--mcl-zones-accent); }
    &:disabled { cursor: default; }
    &[data-state="idle"]:disabled { background: var(--mcl-zones-raise); color: var(--mcl-zones-faint); }
  }
  & .mcl-zones-best:disabled { color: var(--mcl-zones-faint); cursor: default; &:hover { background: none; } }

  @container (max-width: 300px) {
    & .mcl-zones-foot { grid-template-columns: 1fr 1fr; & .mcl-zones-sum { grid-column: 1 / -1; } }
    & .mcl-zones-local { min-width: 54px; & b { font-size: 12px; } }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mcl-zones {
    & .mcl-zones-win { transition: none; }
    & .mcl-zones-win.is-best { animation: none; }
    & .mcl-zones-row { animation: none; }
    & .mcl-zones-fit i { transition: background-color .2s; transition-delay: 0ms; }
    & .mcl-zones-hold[data-state="busy"] span::before { animation-duration: 2.5s; }
  }
}

js:
const $ = s => root.querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const LEN = 45, STEP = 15;
const PEOPLE = [
  { name: 'Ana Ferreira', city: 'Lisbon', tz: 'Europe/Lisbon', ini: 'AF', h: 28, you: true },
  { name: 'Dev Malhotra', city: 'Bengaluru', tz: 'Asia/Kolkata', ini: 'DM', h: 300 },
  { name: 'Wanjiru Kamau', city: 'Nairobi', tz: 'Africa/Nairobi', ini: 'WK', h: 160 },
  { name: 'Theo Laurent', city: 'Toronto', tz: 'America/Toronto', ini: 'TL', h: 230 }
];
const FALLBACK = { 'Europe/Lisbon': 60, 'Asia/Kolkata': 330, 'Africa/Nairobi': 180, 'America/Toronto': -240 };
const ICON = {
  2: '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="2.6"/><path d="M8 1.8v1.4M8 12.8v1.4M1.8 8h1.4M12.8 8h1.4M3.6 3.6l1 1M11.4 11.4l1 1M3.6 12.4l1-1M11.4 4.6l1-1"/></svg>',
  1: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 11.5a5 5 0 0 1 10 0M1.5 11.5h13M8 3v2.2M3.8 5.6l1.2 1.2M12.2 5.6 11 6.8"/></svg>',
  0: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M12.8 9.6A5.2 5.2 0 1 1 6.4 3.2a4.2 4.2 0 0 0 6.4 6.4Z"/></svg>',
  '-1': '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 10.5h11M4 10.5V7.5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v3M3 10.5v2M13 10.5v2"/></svg>'
};
const STATUS = { 2: 'working hours', 1: 'early or late', 0: 'outside hours', '-1': 'weekend' };

/* Intl gives the real offset for that instant, DST included; fall back to fixed offsets */
const fmts = {};
function offsetMin(tz, ms) {
  try {
    const f = fmts[tz] || (fmts[tz] = new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric' }));
    const p = {}; for (const x of f.formatToParts(new Date(ms))) p[x.type] = +x.value;
    return Math.round((Date.UTC(p.year, p.month - 1, p.day, p.hour % 24, p.minute) - Math.floor(ms / 6e4) * 6e4) / 6e4);
  } catch (e) { return FALLBACK[tz] || 0; }
}
const local = (p, ms) => new Date(ms + offsetMin(p.tz, ms) * 6e4);
const clock = d => { const h = d.getUTCHours(), m = d.getUTCMinutes(); return ((h % 12) || 12) + ':' + String(m).padStart(2, '0') + ' ' + (h < 12 ? 'AM' : 'PM'); };
const fDate = new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', weekday: 'short', month: 'short', day: 'numeric' });
const fWeekday = new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', weekday: 'long' });
const list = a => { try { return new Intl.ListFormat('en', { type: 'conjunction' }).format(a); } catch (e) { return a.join(', '); } };
function status(p, ms) {
  const d = local(p, ms), wd = d.getUTCDay(), m = d.getUTCHours() * 60 + d.getUTCMinutes();
  if (wd === 0 || wd === 6) return -1;
  return m >= 540 && m < 1080 ? 2 : m >= 420 && m < 1260 ? 1 : 0;
}

const board = $('[data-board]'), track = $('[data-track]'), win = $('[data-win]'), winTime = $('[data-wintime]');
const fit = $('[data-fit]'), sum = $('[data-sum]'), dateLbl = $('[data-datelabel]'), empty = $('[data-empty]');
const holdBtn = $('[data-hold]'), holdLbl = $('[data-holdlabel]'), bestBtn = $('[data-best]');
const host = PEOPLE[0];

/* rows */
board.insertAdjacentHTML('beforeend', PEOPLE.map((p, i) =>
  '<div class="mcl-zones-row" style="--i:' + i + ';grid-row:' + (i + 3) + '"><span class="mcl-zones-av" style="--h:' + p.h + '" aria-hidden="true">' + p.ini + '</span>' +
  '<p class="mcl-zones-who"><b>' + p.name + '</b> · ' + p.city + (p.you ? '<em>You</em>' : '') + '</p>' +
  '<span class="mcl-zones-strip" aria-hidden="true"></span>' +
  '<p class="mcl-zones-local" data-local><b></b><small></small></p></div>').join(''));
const rows = [...board.querySelectorAll('.mcl-zones-row')].map((el, i) => ({ el, p: PEOPLE[i], strip: el.querySelector('.mcl-zones-strip'), out: el.querySelector('[data-local]') }));
fit.innerHTML = Array.from({ length: 48 }, (_, i) => '<i style="--i:' + i + ';--s:0"></i>').join('');
const bars = [...fit.children];

/* the day being planned, in the host's (Lisbon) calendar */
const now = new Date();
let ymd = (() => { const d = local(host, now.getTime()); return [d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()]; })();
let dayStart = 0, grid = [], t = 0, best = 0, held = null;

function dayStartFor(y, m, d) {
  const guess = Date.UTC(y, m, d, 12);
  return Date.UTC(y, m, d) - offsetMin(host.tz, guess) * 6e4;
}
function score(q) {
  let s = 0;
  const per = grid.map(g => Math.min(g[q], g[q + 1] ?? g[q], g[q + 2] ?? g[q]));
  for (const v of per) s += Math.max(v, 0);
  return { s, per };
}

function build(animate) {
  dayStart = dayStartFor(ymd[0], ymd[1], ymd[2]);
  grid = PEOPLE.map(p => Array.from({ length: 96 }, (_, q) => status(p, dayStart + q * 9e5)));
  const col = { 2: 'var(--mcl-zones-work)', 1: 'var(--mcl-zones-early)', 0: 'var(--mcl-zones-night)', '-1': 'repeating-linear-gradient(135deg, var(--mcl-zones-night) 0 3px, transparent 3px 6px)' };
  rows.forEach((r, i) => {
    /* one hard-stop gradient per person: their whole day in a single paint */
    const g = grid[i], stops = [];
    let a = 0;
    for (let q = 1; q <= 96; q++) {
      if (q === 96 || g[q] !== g[a]) {
        const c = g[a] === -1 ? 'color-mix(in oklch, var(--mcl-zones-ink) 4%, transparent)' : col[g[a]];
        stops.push(c + ' ' + (a / 96 * 100).toFixed(3) + '% ' + (q / 96 * 100).toFixed(3) + '%');
        a = q;
      }
    }
    const ticks = 'repeating-linear-gradient(90deg, transparent 0 calc(100% / 24 - 1px), color-mix(in oklch, var(--mcl-zones-bg) 70%, transparent) calc(100% / 24 - 1px) calc(100% / 24))';
    r.strip.style.setProperty('--g', ticks + ', linear-gradient(90deg, ' + stops.join(', ') + ')');
    if (animate && !RM.matches) r.strip.animate([{ opacity: .2 }, { opacity: 1 }], { duration: 320, easing: 'ease-out' });
  });
  let bq = 0, bs = -1;
  bars.forEach((b, i) => {
    const { s } = score(i * 2);
