    for (const q of [i * 2, i * 2 + 1]) { const v = score(q).s; if (v > bs || (v === bs && Math.abs(q - 52) < Math.abs(bq - 52))) { bs = v; bq = q; } }
  });
  best = bq * STEP;
  const weekend = grid[0].every(v => v === -1);
  empty.hidden = !weekend;
  empty.firstElementChild.textContent = weekend ? fWeekday.format(new Date(Date.UTC(ymd[0], ymd[1], ymd[2]))) + ' — nobody is working.' : '';
  bestBtn.disabled = weekend;
  dateLbl.textContent = fDate.format(new Date(Date.UTC(ymd[0], ymd[1], ymd[2])));
