  const q = t / STEP, { s, per } = score(q), ms = dayStart + t * 6e4;
  winTime.textContent = clock(local(host, ms));
  rows.forEach((r, i) => {
    const d = local(r.p, ms), hostD = local(host, ms), st = per[i];
    const dd = Math.round((Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) - Date.UTC(hostD.getUTCFullYear(), hostD.getUTCMonth(), hostD.getUTCDate())) / 864e5);
    r.out.dataset.st = st;
    r.out.innerHTML = '<b>' + ICON[st] + clock(d) + '</b><small>' + (dd ? (dd > 0 ? 'next day' : 'day before') : STATUS[st]) + '</small>';
  });
  const working = per.filter(v => v === 2).length, early = rows.filter((r, i) => per[i] === 1), off = rows.filter((r, i) => per[i] <= 0);
  const range = clock(local(host, ms)) + '–' + clock(local(host, ms + LEN * 6e4));
  let msg = '<b>' + range.replace(/ (AM|PM)(?=–)/, '') + '</b> Lisbon · ' + working + ' of 4 in hours';
  if (early.length) msg += '; ' + list(early.map(r => r.p.name.split(' ')[0])) + ' early or late';
  if (off.length) msg += '; ' + list(off.map(r => r.p.name.split(' ')[0])) + ' off';
  sum.innerHTML = empty.hidden ? msg + '.' : '<b>' + fWeekday.format(new Date(Date.UTC(ymd[0], ymd[1], ymd[2]))) + '</b> · no shared working hours.';
  track.setAttribute('aria-valuenow', t);
  track.setAttribute('aria-valuetext', clock(local(host, ms)) + ' Lisbon, ' + working + ' of 4 in working hours, fit ' + s + ' of 8');
