  holdBtn.dataset.state = isHeld ? 'held' : 'idle';
  holdBtn.disabled = !!isHeld || !empty.hidden;
  holdLbl.textContent = isHeld ? 'Held' : 'Hold slot';
}

/* pointer: drag anywhere across the strips */
const fromX = x => { const r = track.getBoundingClientRect(); return (x - r.left) / r.width * 1440 - LEN / 2; };
track.addEventListener('pointerdown', e => {
  if (!empty.hidden) return;
  track.setPointerCapture(e.pointerId); track.classList.add('is-drag'); track.focus({ preventScroll: true });
  place(fromX(e.clientX), false);
