function shiftDay(n) {
  const d = new Date(Date.UTC(ymd[0], ymd[1], ymd[2] + n));
  ymd = [d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()];
  build(true);
}
root.querySelectorAll('[data-day]').forEach(b => b.addEventListener('click', () => shiftDay(+b.dataset.day)));
$('[data-nextweekday]').addEventListener('click', () => {
  let n = 1;
  while ([0, 6].includes(new Date(Date.UTC(ymd[0], ymd[1], ymd[2] + n)).getUTCDay())) n++;
