holdBtn.addEventListener('click', () => {
  if (holdBtn.dataset.state !== 'idle') return;
  holdBtn.dataset.state = 'busy'; holdBtn.disabled = true; holdLbl.textContent = 'Holding';
  setTimeout(() => {
    if (!root.isConnected) return;
    held = [ymd.join('-'), t]; place(t, true);
    sum.innerHTML = '<b>Held</b> — calendars blocked for all four; invites go out when you confirm.';
  }, 700);
});

build(false);
place(best, false);

