@property --mcl-timer-a { syntax: '<angle>'; inherits: true; initial-value: 150deg; }
@keyframes mcl-timer-blink { 50% { opacity: .15; } }
@keyframes mcl-timer-breathe { 50% { opacity: .45; } }
@keyframes mcl-timer-pulse {
  0% { box-shadow: var(--mcl-timer-face-shadow), 0 0 0 0 color-mix(in oklch, var(--mcl-timer-accent) 50%, transparent); }
  100% { box-shadow: var(--mcl-timer-face-shadow), 0 0 0 18px transparent; }
}
@keyframes mcl-timer-done { from { opacity: 0; transform: translateY(6px) scale(.96); } }

.mcl-timer {
  /* re-theme with these four */
  --mcl-timer-body: oklch(0.952 0.007 95);
  --mcl-timer-face: oklch(0.993 0.003 95);
  --mcl-timer-ink: oklch(0.22 0.012 95);
  --mcl-timer-accent: oklch(0.6 0.21 27);

  --mcl-timer-mute: color-mix(in oklch, var(--mcl-timer-ink) 55%, var(--mcl-timer-body));
  --mcl-timer-line: color-mix(in oklch, var(--mcl-timer-ink) 12%, transparent);
  --mcl-timer-press: color-mix(in oklch, var(--mcl-timer-ink) 7%, transparent);
  --mcl-timer-face-shadow: 0 1px 0 oklch(1 0 0 / .9) inset, 0 -1px 2px color-mix(in oklch, var(--mcl-timer-ink) 10%, transparent) inset, 0 10px 24px -10px color-mix(in oklch, var(--mcl-timer-ink) 40%, transparent), 0 2px 4px color-mix(in oklch, var(--mcl-timer-ink) 12%, transparent);
  --mcl-timer-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);
  --mcl-timer-out: cubic-bezier(.2, .9, .25, 1);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%;
  display: grid; justify-items: center; gap: 12px;
  grid-template-areas: "head" "dial" "read" "presets" "foot";
  padding: 16px 16px 14px;
  border-radius: 22px;
  background: linear-gradient(180deg, oklch(1 0 0 / .55), transparent 30%), var(--mcl-timer-body);
  border: 1px solid var(--mcl-timer-line);
  box-shadow: 0 1px 0 oklch(1 0 0 / .8) inset, 0 18px 40px -26px color-mix(in oklch, var(--mcl-timer-ink) 50%, transparent);
  color: var(--mcl-timer-ink);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; }
  & :focus-visible { outline: 2px solid var(--mcl-timer-ink); outline-offset: 3px; }

  & .mcl-timer-head { grid-area: head; justify-self: stretch; display: flex; align-items: center; justify-content: space-between; gap: 10px; }
  & .mcl-timer-eyebrow {
    margin: 0; display: inline-flex; align-items: center; gap: 7px;
    font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  }
  & .mcl-timer-led { width: 7px; height: 7px; border-radius: 50%; background: var(--mcl-timer-line); transition: background-color .3s; }
  &[data-state="running"] .mcl-timer-led { background: var(--mcl-timer-accent); animation: mcl-timer-blink 1.2s steps(1) infinite; }
  &[data-state="paused"] .mcl-timer-led { background: var(--mcl-timer-accent); }
  & .mcl-timer-today { margin: 0; font-size: 11px; color: var(--mcl-timer-mute); font-variant-numeric: tabular-nums; text-align: right; }

  /* ---------- the dial ---------- */
  & .mcl-timer-dial {
    grid-area: dial; width: min(216px, 66cqi); aspect-ratio: 1; border-radius: 50%;
    cursor: grab; touch-action: none; outline-offset: 6px;
    &:active { cursor: grabbing; }
  }
  & .mcl-timer-face {
    position: relative; width: 100%; height: 100%; border-radius: 50%;
    background: radial-gradient(circle at 50% 35%, var(--mcl-timer-face), color-mix(in oklch, var(--mcl-timer-face) 92%, var(--mcl-timer-ink)));
    box-shadow: var(--mcl-timer-face-shadow);
  }
  & .mcl-timer-wedge {
    position: absolute; inset: 16%; border-radius: 50%;
    background:
      radial-gradient(circle, oklch(1 0 0 / .14), transparent 70%),
      conic-gradient(from calc(-1 * var(--mcl-timer-a)), var(--mcl-timer-accent) 0 var(--mcl-timer-a), transparent 0);
  }
  & .mcl-timer-scale {
    position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible;
    & line { stroke: var(--mcl-timer-ink); stroke-width: 1; }
    & line.is-long { stroke-width: 2; }
    & text { fill: var(--mcl-timer-ink); stroke: none; font: 650 10.5px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; text-anchor: middle; dominant-baseline: central; }
  }
  & .mcl-timer-hand {
    position: absolute; left: calc(50% - 1px); top: 16%; width: 2px; height: 34%; border-radius: 2px;
    background: color-mix(in oklch, var(--mcl-timer-accent) 60%, black); transform-origin: 50% 100%;
    rotate: calc(-1 * var(--mcl-timer-a));
  }
  & .mcl-timer-knob {
    position: absolute; inset: 41%; border-radius: 50%;
    background: radial-gradient(circle at 40% 35%, var(--mcl-timer-face), color-mix(in oklch, var(--mcl-timer-face) 85%, var(--mcl-timer-ink)));
    box-shadow: 0 2px 5px color-mix(in oklch, var(--mcl-timer-ink) 30%, transparent), 0 0 0 1px var(--mcl-timer-line);
  }
  &.is-ease { transition: --mcl-timer-a .7s var(--mcl-timer-spring); }

  /* ---------- readout ---------- */
  & .mcl-timer-readout { grid-area: read; display: grid; justify-items: center; gap: 1px; text-align: center; }
  & .mcl-timer-time {
    margin: 0; font: 300 clamp(34px, 12cqi, 44px)/1 system-ui, -apple-system, sans-serif;
    letter-spacing: -.03em; font-variant-numeric: tabular-nums;
  }
  &[data-state="paused"] .mcl-timer-time { animation: mcl-timer-breathe 1.8s ease-in-out infinite; }
  &[data-state="done"] .mcl-timer-time { color: var(--mcl-timer-accent); font-weight: 500; animation: mcl-timer-done .5s var(--mcl-timer-out); }
  &[data-state="done"] .mcl-timer-face { animation: mcl-timer-pulse 1.1s ease-out 3; }
  & .mcl-timer-task { margin: 4px 0 0; font-size: 12.5px; font-weight: 600; text-wrap: balance; }
  & .mcl-timer-status { margin: 0; min-height: 17px; font-size: 11.5px; color: var(--mcl-timer-mute); font-variant-numeric: tabular-nums; }

  /* ---------- presets ---------- */
  & .mcl-timer-presets { grid-area: presets; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; justify-self: stretch; }
  & .mcl-timer-presets button {
    height: 34px; padding: 0; border: 0; border-radius: 10px; cursor: pointer;
    background: var(--mcl-timer-press); font-size: 14px; font-weight: 650; font-variant-numeric: tabular-nums;
    display: inline-flex; align-items: baseline; justify-content: center; gap: 2px;
    transition: background-color .2s, color .2s, scale .3s var(--mcl-timer-spring);
    & span { font-size: 10px; font-weight: 600; color: var(--mcl-timer-mute); transition: color .2s; }
    &:hover { background: color-mix(in oklch, var(--mcl-timer-ink) 11%, transparent); }
    &:active { scale: .94; }
    &[aria-pressed="true"] { background: var(--mcl-timer-ink); color: var(--mcl-timer-face); & span { color: color-mix(in oklch, var(--mcl-timer-face) 65%, transparent); } }
  }

  /* ---------- actions ---------- */
  & .mcl-timer-foot { grid-area: foot; justify-self: stretch; display: grid; grid-template-columns: auto 1fr; gap: 8px; }
  & .mcl-timer-reset {
    width: 42px; height: 42px; padding: 0; border: 0; border-radius: 50%; cursor: pointer; display: grid; place-items: center;
    background: var(--mcl-timer-press); transition: background-color .2s, rotate .5s var(--mcl-timer-out);
    & svg { width: 17px; height: 17px; }
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--mcl-timer-ink) 11%, transparent); }
    &:active:not(:disabled) { rotate: -60deg; }
    &:disabled { color: color-mix(in oklch, var(--mcl-timer-ink) 28%, transparent); cursor: default; }
  }
  & .mcl-timer-go {
    height: 42px; border: 0; border-radius: 21px; cursor: pointer;
    display: inline-flex; align-items: center; justify-content: center; gap: 8px;
    background: var(--mcl-timer-accent); color: oklch(0.99 0.01 27); font-size: 14px; font-weight: 650; letter-spacing: .01em;
    box-shadow: 0 1px 0 oklch(1 0 0 / .25) inset, 0 6px 14px -6px color-mix(in oklch, var(--mcl-timer-accent) 70%, transparent);
    transition: background-color .2s, scale .3s var(--mcl-timer-spring), box-shadow .2s;
    & svg { width: 15px; height: 15px; }
    & .mcl-timer-play { fill: currentColor; stroke-width: 1.2; }
    & .mcl-timer-pause { display: none; stroke-width: 2.2; }
    &:active:not(:disabled) { scale: .97; }
    &:disabled { background: var(--mcl-timer-press); color: var(--mcl-timer-mute); box-shadow: none; cursor: default; }
  }
  &[data-state="running"] .mcl-timer-go {
    background: var(--mcl-timer-ink); box-shadow: none;
    & .mcl-timer-play { display: none; }
    & .mcl-timer-pause { display: block; }
  }

  @container (max-width: 270px) {
    & .mcl-timer-today { display: none; }
    & .mcl-timer-presets button span { display: none; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mcl-timer {
    &.is-ease { transition: --mcl-timer-a .2s linear; }
    &[data-state="running"] .mcl-timer-led, &[data-state="paused"] .mcl-timer-time,
    &[data-state="done"] .mcl-timer-time, &[data-state="done"] .mcl-timer-face { animation: none; }
    &[data-state="done"] .mcl-timer-face { box-shadow: var(--mcl-timer-face-shadow), 0 0 0 3px var(--mcl-timer-accent); }
    & .mcl-timer-presets button, & .mcl-timer-go, & .mcl-timer-reset { transition: background-color .2s, color .2s; }
  }
}

