const $ = s => root.querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const dial = $('[data-dial]'), readEl = $('[data-read]'), statusEl = $('[data-status]'), todayEl = $('[data-today]');
const go = $('[data-go]'), goLbl = $('[data-golabel]'), resetBtn = $('[data-reset]'), presetsEl = $('[data-presets]'), modeEl = $('[data-mode]');
const MAX = 3600;

/* scale: numbers count counter-clockwise from 12 o'clock, like a mechanical timer */
let svg = '';
for (let i = 0; i < 60; i++) {
  const a = -i * 6 * Math.PI / 180, long = i % 5 === 0, r1 = long ? 70 : 73.5, r2 = 77.5;
  svg += '<line' + (long ? ' class="is-long"' : '') + ' x1="' + (100 + r1 * Math.sin(a)).toFixed(2) + '" y1="' + (100 - r1 * Math.cos(a)).toFixed(2) +
    '" x2="' + (100 + r2 * Math.sin(a)).toFixed(2) + '" y2="' + (100 - r2 * Math.cos(a)).toFixed(2) + '"/>';
  if (long) svg += '<text x="' + (100 + 88 * Math.sin(a)).toFixed(2) + '" y="' + (100 - 88 * Math.cos(a)).toFixed(2) + '">' + i + '</text>';
}
$('[data-scale]').innerHTML = svg;

let total = 25 * 60, left = total, state = 'idle', endAt = 0, raf = 0, doneT = 0, visible = true, lastShown = -1;
let sessions = 2, focusedMin = 50;
const mmss = s => String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');
const hm = m => [m >= 60 ? Math.floor(m / 60) + ' h' : '', m % 60 || m < 60 ? (m % 60) + ' min' : ''].filter(Boolean).join(' ');
const clock = d => { const h = d.getHours(); return ((h % 12) || 12) + ':' + String(d.getMinutes()).padStart(2, '0') + ' ' + (h < 12 ? 'AM' : 'PM'); };

function ease(on) { root.classList.toggle('is-ease', on && !RM.matches); }
function draw(force) {
  root.style.setProperty('--mcl-timer-a', (Math.max(0, left) / MAX * 360).toFixed(3) + 'deg');
  const s = Math.max(0, Math.ceil(left - 1e-6));
  if (s === lastShown && !force) return;
  lastShown = s;
  readEl.textContent = state === 'done' ? 'Time’s up' : mmss(s);
  const mins = Math.ceil(s / 60);
  dial.setAttribute('aria-valuenow', mins);
  dial.setAttribute('aria-valuetext', s ? mmss(s).replace(':', ' minutes ') + ' seconds remaining' : 'No time set');
}
function ui() {
  root.dataset.state = state;
  const set = Math.round(total / 60);
  presetsEl.querySelectorAll('button').forEach(b => b.setAttribute('aria-pressed', String(+b.dataset.min === set && state !== 'done')));
  go.disabled = state === 'idle' && left <= 0;
  goLbl.textContent = state === 'running' ? 'Pause' : state === 'paused' ? 'Resume' : state === 'done' ? 'Again · ' + set + ' min' : 'Start';
  resetBtn.disabled = state === 'idle' && left === total;
  modeEl.textContent = state === 'running' ? 'Focusing' : state === 'paused' ? 'Paused' : state === 'done' ? 'Done' : 'Focus timer';
  statusEl.textContent =
    state === 'running' ? 'Ends at ' + clock(new Date(Date.now() + left * 1000)) :
    state === 'paused' ? mmss(Math.ceil(left)) + ' left · paused' :
    state === 'done' ? set + ' min logged — take five.' :
    left > 0 ? 'Ready · ' + Math.ceil(left / 60) + ' min' : 'Drag the dial or pick a length.';
  todayEl.textContent = 'Session ' + (sessions + (state === 'done' ? 0 : 1)) + ' · ' + hm(focusedMin) + ' today';
  draw(true);
}

function frame() {
  if (!root.isConnected) return;
  raf = 0;
  if (state !== 'running') return;
  left = (endAt - performance.now()) / 1000;
  if (left <= 0) { finish(); return; }
  draw();
  if (visible) raf = requestAnimationFrame(frame);
}
function loop() { if (!raf && visible && state === 'running') raf = requestAnimationFrame(frame); }
function arm() {
  clearTimeout(doneT);
  doneT = setTimeout(() => { if (root.isConnected && state === 'running') finish(); }, left * 1000 + 40);
}
function start() {
  if (left <= 0) return;
  ease(false); state = 'running'; endAt = performance.now() + left * 1000; arm(); ui(); loop();
}
function pause() {
  left = Math.max(0, (endAt - performance.now()) / 1000);
  state = 'paused'; clearTimeout(doneT); cancelAnimationFrame(raf); raf = 0; ui();
}
function finish() {
  clearTimeout(doneT); cancelAnimationFrame(raf); raf = 0;
  left = 0; state = 'done'; sessions++; focusedMin += Math.round(total / 60);
  ease(true); ui();
}
function setSeconds(sec, opts) {
  sec = Math.max(0, Math.min(MAX, sec));
  if (state === 'done') state = 'idle';
  left = sec;
  if (!opts || !opts.keepTotal) total = sec;
  if (state === 'running') { endAt = performance.now() + left * 1000; arm(); if (left <= 0) { state = 'idle'; } }
  else if (state === 'paused' && left <= 0) state = 'idle';
  else if (state === 'paused') total = Math.max(total, sec);
  ui();
}

/* dragging the dial: angle measured counter-clockwise from 12, snapped to whole minutes */
let dragging = false, lastMin = 0;
function minutesAt(e) {
  const r = dial.getBoundingClientRect(), x = e.clientX - (r.left + r.width / 2), y = e.clientY - (r.top + r.height / 2);
  const cw = (Math.atan2(x, -y) * 180 / Math.PI + 360) % 360;
  return Math.round(((360 - cw) % 360) / 6);
}
function dragTo(e) {
  let m = minutesAt(e);
  if (lastMin > 45 && m < 15) m = 60;
  else if (lastMin < 15 && m > 45) m = 0;
  if (m === lastMin && dragging) return;
  lastMin = m;
  setSeconds(m * 60);
}
dial.addEventListener('pointerdown', e => {
  if (e.button !== 0) return;
