dial.addEventListener('pointermove', e => { if (!dragging) return; ease(false); dragTo(e); });
const end = () => { dragging = false; };
dial.addEventListener('pointerup', end);
dial.addEventListener('pointercancel', end);
dial.addEventListener('keydown', e => {
  const m = Math.ceil(left / 60 - 1e-6);
  const map = { ArrowUp: m + 1, ArrowRight: m + 1, ArrowDown: m - 1, ArrowLeft: m - 1, PageUp: m + 5, PageDown: m - 5, Home: 0, End: 60 };
