  const b = e.target.closest('button');
  if (!b) return;
  ease(state !== 'running');
  setSeconds(+b.dataset.min * 60);
});
go.addEventListener('click', () => {
  if (state === 'running') pause();
  else if (state === 'done') { ease(true); left = total; state = 'idle'; ui(); setTimeout(() => { if (root.isConnected) start(); }, RM.matches ? 0 : 450); }
