resetBtn.addEventListener('click', () => {
  clearTimeout(doneT); cancelAnimationFrame(raf); raf = 0;
  ease(true); state = 'idle'; left = total; ui();
});

const io = new IntersectionObserver(es => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) { if (state === 'running') { left = (endAt - performance.now()) / 1000; draw(); } loop(); }
});
io.observe(root);

ease(false);
ui();
requestAnimationFrame(() => { if (!root.isConnected) return; ease(true); });

