@keyframes mcl-bezel-day { to { transform: rotate(-360deg); } }
@keyframes mcl-bezel-sweep { to { transform: rotate(360deg); } }
@keyframes mcl-bezel-swap { from { opacity: 0; filter: blur(3px); transform: translateY(4px); } }
@property --mcl-bezel-ft { syntax: '<length>'; inherits: false; initial-value: 0px; }
@property --mcl-bezel-fb { syntax: '<length>'; inherits: false; initial-value: 0px; }
@keyframes mcl-bezel-fade { 0% { --mcl-bezel-ft: 0px; --mcl-bezel-fb: 22px; } 12%, 88% { --mcl-bezel-ft: 22px; --mcl-bezel-fb: 22px; } 100% { --mcl-bezel-ft: 22px; --mcl-bezel-fb: 0px; } }

.mcl-bezel {
  /* re-theme with these four */
  --mcl-bezel-bg: oklch(0.255 0.045 162);
  --mcl-bezel-ink: oklch(0.95 0.03 92);
  --mcl-bezel-brass: oklch(0.8 0.115 82);
  --mcl-bezel-night: oklch(0.2 0.035 215);

  --mcl-bezel-mute: color-mix(in oklch, var(--mcl-bezel-ink) 58%, var(--mcl-bezel-bg));
  --mcl-bezel-line: color-mix(in oklch, var(--mcl-bezel-ink) 13%, transparent);
  --mcl-bezel-raise: color-mix(in oklch, var(--mcl-bezel-ink) 6%, transparent);
  --mcl-bezel-ring: color-mix(in oklch, var(--mcl-bezel-bg) 70%, black);
  --mcl-bezel-day: color-mix(in oklch, var(--mcl-bezel-ink) 92%, var(--mcl-bezel-brass));
  --mcl-bezel-dusk: color-mix(in oklch, var(--mcl-bezel-brass) 58%, black);
  --mcl-bezel-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%;
  display: grid; gap: 12px; grid-template-areas: "head" "dial" "list";
  padding: 16px 16px 12px;
  border-radius: 20px; border: 1px solid var(--mcl-bezel-line);
  background:
    radial-gradient(90% 55% at 50% 30%, color-mix(in oklch, var(--mcl-bezel-ink) 7%, transparent), transparent 70%),
    var(--mcl-bezel-bg);
  color: var(--mcl-bezel-ink);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--mcl-bezel-brass); outline-offset: 2px; }

  & .mcl-bezel-head { grid-area: head; display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
  & .mcl-bezel-title { margin: 0; font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--mcl-bezel-brass); }
  & .mcl-bezel-utc { margin: 0; font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--mcl-bezel-mute); font-variant-numeric: tabular-nums; }

  /* ---------- the dial ---------- */
  & .mcl-bezel-dialwrap { grid-area: dial; position: relative; justify-self: center; width: min(250px, 80cqi); aspect-ratio: 1; }
  & .mcl-bezel-svg {
    display: block; width: 100%; height: 100%; overflow: visible;
    filter: drop-shadow(0 10px 18px oklch(0 0 0 / .35));
    & .mcl-bezel-turn { transform-box: view-box; transform-origin: 130px 130px; transition: rotate 1.1s var(--mcl-bezel-spring); }
    & .mcl-bezel-hours { transform-box: view-box; transform-origin: 130px 130px; animation: mcl-bezel-day 86400s linear infinite; }
    & .mcl-bezel-bez { fill: none; stroke: var(--mcl-bezel-ring); stroke-width: 22; }
    & .mcl-bezel-rim { fill: none; stroke: var(--mcl-bezel-line); stroke-width: 1; }
    & path[data-k="day"] { fill: var(--mcl-bezel-day); }
    & path[data-k="dusk"] { fill: var(--mcl-bezel-dusk); }
    & path[data-k="night"] { fill: var(--mcl-bezel-night); }
    & .mcl-bezel-num { font: 650 8.5px/1 system-ui, sans-serif; text-anchor: middle; dominant-baseline: central; font-variant-numeric: tabular-nums; }
    & .mcl-bezel-num[data-k="day"] { fill: var(--mcl-bezel-bg); }
    & .mcl-bezel-num[data-k="dusk"], & .mcl-bezel-num[data-k="night"] { fill: var(--mcl-bezel-ink); }
    & .mcl-bezel-code {
      font: 700 7.6px/1 system-ui, sans-serif; letter-spacing: .12em; text-anchor: middle; dominant-baseline: central;
      fill: var(--mcl-bezel-mute); cursor: pointer; transition: fill .3s;
    }
    & .mcl-bezel-code[aria-current="true"] { fill: var(--mcl-bezel-brass); }
    & .mcl-bezel-here { fill: var(--mcl-bezel-brass); }
    & .mcl-bezel-index { fill: var(--mcl-bezel-brass); }
    & .mcl-bezel-dot { fill: var(--mcl-bezel-brass); }
    & .mcl-bezel-tick { stroke: var(--mcl-bezel-line); stroke-width: 1; }
  }
  & .mcl-bezel-center {
    position: absolute; inset: 17.7%; border-radius: 50%; pointer-events: none;
    display: grid; place-content: center; justify-items: center; text-align: center; gap: 1px;
    background:
      radial-gradient(circle at 50% 30%, color-mix(in oklch, var(--mcl-bezel-ink) 9%, transparent), transparent 65%),
      color-mix(in oklch, var(--mcl-bezel-bg) 88%, black);
    box-shadow: inset 0 2px 10px oklch(0 0 0 / .45), inset 0 0 0 1px var(--mcl-bezel-line);
    & p { margin: 0; }
    /* seconds: a brass bead sweeping the inner rim, synced by a negative delay */
    &::before {
      content: ""; position: absolute; inset: 5px; border-radius: 50%;
      background: radial-gradient(circle at 50% 3px, var(--mcl-bezel-brass) 2.2px, transparent 2.8px);
      animation: mcl-bezel-sweep 60s linear infinite; animation-delay: var(--mcl-bezel-sd, 0s);
    }
  }
  & .mcl-bezel-time {
    font: 300 clamp(26px, 10cqi, 36px)/1 system-ui, -apple-system, sans-serif; letter-spacing: -.02em; font-variant-numeric: tabular-nums;
    & small { font-size: .42em; font-weight: 500; letter-spacing: 0; color: var(--mcl-bezel-brass); margin-left: 1px; vertical-align: .9em; }
  }
  & .mcl-bezel-city { margin-top: 4px !important; max-width: 46cqi; font-size: clamp(10.5px, 3.6cqi, 12.5px); font-weight: 650; letter-spacing: .01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .mcl-bezel-date { font-size: 10.5px; color: var(--mcl-bezel-mute); font-variant-numeric: tabular-nums; }
  & .mcl-bezel-center.is-swap :is(.mcl-bezel-city, .mcl-bezel-date, [data-hm]) { animation: mcl-bezel-swap .4s cubic-bezier(.2, .9, .25, 1); }

  /* ---------- city list ---------- */
  & .mcl-bezel-list {
    grid-area: list; max-height: 176px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin;
    scrollbar-color: var(--mcl-bezel-line) transparent; margin-inline: -6px; padding: 2px 6px;
    border-top: 1px solid var(--mcl-bezel-line);
  }
  & .mcl-bezel-opt {
    display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; grid-template-areas: "icon name time" "icon rel time";
    align-items: center; column-gap: 10px; padding: 7px 8px; margin-top: 2px; border-radius: 10px; cursor: pointer;
    transition: background-color .2s;
    & svg { grid-area: icon; width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; color: var(--mcl-bezel-mute); }
    &[data-day] svg { color: var(--mcl-bezel-brass); }
    & b { grid-area: name; font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & b small { margin-left: 6px; font: 600 9.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; color: var(--mcl-bezel-mute); }
    & span { grid-area: rel; font-size: 11px; color: var(--mcl-bezel-mute); font-variant-numeric: tabular-nums; white-space: nowrap; }
    & time { grid-area: time; font-size: 15px; font-weight: 500; font-variant-numeric: tabular-nums; letter-spacing: -.01em; }
    & em { font-style: normal; margin-left: 6px; padding: 1px 5px; border-radius: 4px; font-size: 9.5px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; background: var(--mcl-bezel-raise); color: var(--mcl-bezel-ink); }
    &:hover { background: var(--mcl-bezel-raise); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--mcl-bezel-brass) 15%, transparent); & time { color: var(--mcl-bezel-brass); } }
    &:focus-visible { outline-offset: -2px; }
  }

  @container (max-width: 280px) {
    & .mcl-bezel-opt { column-gap: 8px; padding-inline: 6px; & time { font-size: 13px; } }
  }
}

@supports (animation-timeline: scroll()) {
  .mcl-bezel .mcl-bezel-list {
    mask-image: linear-gradient(transparent, #000 var(--mcl-bezel-ft), #000 calc(100% - var(--mcl-bezel-fb)), transparent);
    animation: mcl-bezel-fade linear both;
    animation-timeline: scroll(self block);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mcl-bezel {
    & .mcl-bezel-svg .mcl-bezel-turn { transition: rotate .25s ease-out; }
    & .mcl-bezel-center::before { animation: none; opacity: 0; }
    & .mcl-bezel-center.is-swap :is(.mcl-bezel-city, .mcl-bezel-date, [data-hm]) { animation: none; }
  }
}

