const $ = s => root.querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const CITIES = [
  ['Honolulu', 'HNL', 'Pacific/Honolulu', -600], ['Vancouver', 'YVR', 'America/Vancouver', -420],
  ['Mexico City', 'MEX', 'America/Mexico_City', -360], ['New York', 'NYC', 'America/New_York', -240],
  ['São Paulo', 'GRU', 'America/Sao_Paulo', -180], ['Reykjavík', 'REK', 'Atlantic/Reykjavik', 0],
  ['Berlin', 'BER', 'Europe/Berlin', 120], ['Nairobi', 'NBO', 'Africa/Nairobi', 180],
  ['Dubai', 'DXB', 'Asia/Dubai', 240], ['Mumbai', 'BOM', 'Asia/Kolkata', 330],
  ['Bangkok', 'BKK', 'Asia/Bangkok', 420], ['Tokyo', 'TYO', 'Asia/Tokyo', 540], ['Sydney', 'SYD', 'Australia/Sydney', 600]
].map(c => ({ name: c[0], code: c[1], tz: c[2], fb: c[3] }));
let localTz = 'UTC';
try { localTz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'; } catch (e) {}
const local = { name: (localTz.split('/').pop() || 'Local').replace(/_/g, ' '), code: 'YOU', tz: localTz, fb: -new Date().getTimezoneOffset(), you: true };
const LIST = [local].concat(CITIES);

const fmts = {};
function offsetMin(c, ms) {
  try {
    const f = fmts[c.tz] || (fmts[c.tz] = new Intl.DateTimeFormat('en-US', { timeZone: c.tz, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric' }));
    const p = {}; for (const x of f.formatToParts(new Date(ms))) p[x.type] = +x.value;
    return Math.round((Date.UTC(p.year, p.month - 1, p.day, p.hour % 24, p.minute) - Math.floor(ms / 6e4) * 6e4) / 6e4);
  } catch (e) { return c.fb; }
}
const fDate = new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', weekday: 'short', month: 'short', day: 'numeric' });
const p2 = n => String(n).padStart(2, '0');
const offLabel = m => 'UTC' + (m < 0 ? '−' : '+') + Math.floor(Math.abs(m) / 60) + (Math.abs(m) % 60 ? ':' + p2(Math.abs(m) % 60) : '');
const relLabel = d => !d ? 'Same time' : (d > 0 ? '+' : '−') + Math.floor(Math.abs(d) / 60) + ' h' + (Math.abs(d) % 60 ? ' ' + (Math.abs(d) % 60) + ' min' : '');
const kind = h => h >= 6 && h < 18 ? 'day' : h === 5 || h === 18 || h === 19 ? 'dusk' : 'night';
const SUN = '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="2.8"/><path d="M8 1.6v1.6M8 12.8v1.6M1.6 8h1.6M12.8 8h1.6M3.5 3.5l1.1 1.1M11.4 11.4l1.1 1.1M3.5 12.5l1.1-1.1M11.4 4.6l1.1-1.1"/></svg>';
const MOON = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M12.8 9.8A5.2 5.2 0 1 1 6.2 3.2a4.2 4.2 0 0 0 6.6 6.6Z"/></svg>';

const svg = $('[data-svg]'), list = $('[data-list]'), center = $('[data-center]');
const hmEl = $('[data-hm]'), sEl = $('[data-s]'), cName = $('[data-cname]'), cDate = $('[data-cdate]'), utcEl = $('[data-utc]');
const C = 130, pt = (r, deg) => [C + r * Math.sin(deg * Math.PI / 180), C - r * Math.cos(deg * Math.PI / 180)];
const f2 = n => n.toFixed(2);

/* ---------- build the dial ---------- */
const now0 = Date.now();
LIST.forEach(c => { c.off = offsetMin(c, now0); });
let s = '<circle class="mcl-bezel-bez" cx="130" cy="130" r="115"/><circle class="mcl-bezel-rim" cx="130" cy="130" r="126"/>';
s += '<g class="mcl-bezel-turn" data-turn>';
/* the 24-hour ring: annular sectors, one per hour, turning once a day */
s += '<g class="mcl-bezel-hours" data-hours>';
for (let h = 0; h < 24; h++) {
  const a0 = h * 15 - 7.5, a1 = a0 + 15, k = kind(h);
  const [x0, y0] = pt(104, a0), [x1, y1] = pt(104, a1), [x2, y2] = pt(84, a1), [x3, y3] = pt(84, a0);
  s += '<path data-k="' + k + '" d="M' + f2(x0) + ' ' + f2(y0) + 'A104 104 0 0 1 ' + f2(x1) + ' ' + f2(y1) + 'L' + f2(x2) + ' ' + f2(y2) + 'A84 84 0 0 0 ' + f2(x3) + ' ' + f2(y3) + 'Z"/>';
  const [tx, ty] = pt(94, h * 15);
  s += '<text class="mcl-bezel-num" data-k="' + k + '" x="' + f2(tx) + '" y="' + f2(ty) + '" transform="rotate(' + (h * 15) + ' ' + f2(tx) + ' ' + f2(ty) + ')">' + h + '</text>';
}
s += '</g>';
/* city codes on the bezel, 15 degrees per hour of offset */
for (let h = 0; h < 24; h++) { const [a, b] = pt(104.5, h * 15), [c, d] = pt(107.5, h * 15); s += '<line class="mcl-bezel-tick" x1="' + f2(a) + '" y1="' + f2(b) + '" x2="' + f2(c) + '" y2="' + f2(d) + '"/>'; }
LIST.forEach((c, i) => {
  const deg = c.off / 60 * 15;
  if (c.you) { const [x, y] = pt(121.5, deg); s += '<circle class="mcl-bezel-here" cx="' + f2(x) + '" cy="' + f2(y) + '" r="2"/>'; return; }
  s += '<text class="mcl-bezel-code" data-i="' + i + '" x="130" y="15" transform="rotate(' + deg + ' 130 130)">' + c.code + '</text>';
