s += '</g>';
s += '<path class="mcl-bezel-index" d="M125.5 22.5h9L130 30.5Z"/>';
svg.innerHTML = s;
const turn = $('[data-turn]'), hours = $('[data-hours]');

/* pure-CSS clock hands: a negative delay drops each animation at the current instant */
function sync() {
  const t = Date.now(), dayS = (t % 864e5) / 1000;
  hours.style.animationDelay = (-dayS) + 's';
  center.style.setProperty('--mcl-bezel-sd', (-(t % 6e4) / 1000) + 's');
}

/* ---------- list ---------- */
list.innerHTML = LIST.map((c, i) => '<div class="mcl-bezel-opt" role="option" tabindex="-1" aria-selected="false" data-i="' + i + '">' +
  '<i hidden></i><b>' + c.name + (c.you ? '<em>You</em>' : '<small>' + c.code + '</small>') + '</b><span></span><time></time></div>').join('');
const opts = [...list.children];

let sel = 0, rot = 0, lastMin = -1;
function localParts(c, t) { const d = new Date(t + offsetMin(c, t) * 6e4); return { h: d.getUTCHours(), m: d.getUTCMinutes(), s: d.getUTCSeconds(), day: Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()), d }; }

function paintList(t) {
  const sc = LIST[sel], so = offsetMin(sc, t), sp = localParts(sc, t);
  opts.forEach((o, i) => {
    const c = LIST[i], lp = localParts(c, t), off = offsetMin(c, t), dd = Math.round((lp.day - sp.day) / 864e5);
    const day = lp.h >= 6 && lp.h < 18;
    o.toggleAttribute('data-day', day);
    o.querySelector('i, svg').outerHTML = day ? SUN : MOON;
    o.querySelector('time').textContent = p2(lp.h) + ':' + p2(lp.m);
    o.querySelector('span').textContent = (i === sel ? offLabel(off) : relLabel(off - so)) + (dd ? (dd > 0 ? ' · tomorrow' : ' · yesterday') : '');
  });
}
function paintCenter(t) {
  const c = LIST[sel], lp = localParts(c, t);
  hmEl.textContent = p2(lp.h) + ':' + p2(lp.m);
  sEl.textContent = ':' + p2(lp.s);
  const u = new Date(t);
  utcEl.textContent = 'UTC ' + p2(u.getUTCHours()) + ':' + p2(u.getUTCMinutes());
}
function tick(force) {
  const t = Date.now(), m = Math.floor(t / 6e4);
  paintCenter(t);
  if (m !== lastMin || force) { lastMin = m; paintList(t); }
}

function select(i, focus) {
  sel = i;
  const c = LIST[i], t = Date.now();
  c.off = offsetMin(c, t);
  const target = -c.off / 60 * 15;
