  cName.textContent = c.name;
  const lp = localParts(c, t);
  cDate.textContent = fDate.format(new Date(lp.day)) + ' · ' + offLabel(c.off);
  if (focus) { opts[i].focus({ preventScroll: true }); opts[i].scrollIntoView({ block: 'nearest' }); }
  if (!RM.matches) { center.classList.remove('is-swap'); void center.offsetWidth; center.classList.add('is-swap'); }
  tick(true);
}

list.addEventListener('click', e => { const o = e.target.closest('[role="option"]'); if (o) select(+o.dataset.i, true); });
list.addEventListener('keydown', e => {
  const k = { ArrowDown: sel + 1, ArrowUp: sel - 1, Home: 0, End: LIST.length - 1 }[e.key];
  if (k == null) return;
  e.preventDefault();
  select(Math.max(0, Math.min(LIST.length - 1, k)), true);
});
svg.addEventListener('click', e => { const t = e.target.closest('.mcl-bezel-code'); if (t) select(+t.dataset.i, false); });

let visible = true;
const io = new IntersectionObserver(es => { if (!root.isConnected) { io.disconnect(); return; } visible = es[es.length - 1].isIntersecting; if (visible) { sync(); tick(true); } });
io.observe(root);
const iv = setInterval(() => {
  if (!root.isConnected) { clearInterval(iv); io.disconnect(); return; }
  if (document.hidden || !visible) return;
  tick(false);
}, 1000);

turn.style.transition = 'none';
sync();
select(0, false);
void svg.getBoundingClientRect();
turn.style.transition = '';

