@keyframes mcl-recur-shake { 25% { translate: -3px 0; } 75% { translate: 3px 0; } }

.mcl-recur {
  /* re-theme with these four */
  --mcl-recur-paper: oklch(0.984 0.005 110);
  --mcl-recur-ink: oklch(0.24 0.012 250);
  --mcl-recur-accent: oklch(0.76 0.145 74);
  --mcl-recur-bad: oklch(0.55 0.19 28);

  --mcl-recur-mute: color-mix(in oklch, var(--mcl-recur-ink) 56%, var(--mcl-recur-paper));
  --mcl-recur-faint: color-mix(in oklch, var(--mcl-recur-ink) 30%, var(--mcl-recur-paper));
  --mcl-recur-line: color-mix(in oklch, var(--mcl-recur-ink) 12%, transparent);
  --mcl-recur-well: color-mix(in oklch, var(--mcl-recur-ink) 5%, transparent);
  --mcl-recur-tint: color-mix(in oklch, var(--mcl-recur-accent) 22%, transparent);
