const $ = s => root.querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const DAY = 864e5, WINDOW = 182, MAXN = 400;
const F = o => new Intl.DateTimeFormat('en-US', Object.assign({ timeZone: 'UTC' }, o));
const fRow = F({ weekday: 'short', month: 'short', day: 'numeric' }), fMD = F({ month: 'short', day: 'numeric' });
const fMDY = F({ month: 'short', day: 'numeric', year: 'numeric' }), fMon = F({ month: 'short' });
const rtf = new Intl.RelativeTimeFormat('en', { numeric: 'auto' });
const WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const ORD = ['first', 'second', 'third', 'fourth', 'fifth'];
const dn = (y, m, d) => Math.round(Date.UTC(y, m, d) / DAY);
const P = n => { const d = new Date(n * DAY); return { y: d.getUTCFullYear(), m: d.getUTCMonth(), d: d.getUTCDate(), w: (d.getUTCDay() + 6) % 7 }; };
const iso = n => new Date(n * DAY).toISOString().slice(0, 10);
const fromIso = s => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || ''); return m ? dn(+m[1], +m[2] - 1, +m[3]) : null; };
const dim = (y, m) => P(dn(y, m + 1, 0)).d;
const listJoin = a => { try { return new Intl.ListFormat('en', { type: 'conjunction' }).format(a); } catch (e) { return a.join(', '); } };

const now = new Date(), today = dn(now.getFullYear(), now.getMonth(), now.getDate());
const startDefault = today + ((3 - P(today).w + 7) % 7); /* the next Thursday */

const startEl = $('[data-start]'), intEl = $('[data-int]'), freqEl = $('[data-freq]'), daysEl = $('[data-days]'), monEl = $('[data-monthly]');
const untilEl = $('[data-until]'), countEl = $('[data-count]'), sumEl = $('[data-sum]'), listEl = $('[data-list]'), railEl = $('[data-rail]');
const monthsEl = $('[data-months]'), totalEl = $('[data-total]'), decBtn = $('[data-dec]'), incBtn = $('[data-inc]');

let days = new Set([3]), monthly = 'day';
startEl.value = iso(startDefault);
untilEl.value = iso(startDefault + 91);
daysEl.innerHTML = WD.map((w, i) => '<button type="button" class="mcl-recur-day" data-w="' + i + '" aria-pressed="' + days.has(i) + '" aria-label="' + w + '">' + w[0] + '</button>').join('');

/* rebuilt only when the start date changes, so a focused radio is never replaced under the user */
let monFor = null;
function monthlyOptions(s) {
  const p = P(s);
  if (monFor !== s) {
    monFor = s;
    const nth = Math.ceil(p.d / 7), last = p.d + 7 > dim(p.y, p.m);
    const o = [['day', 'Day ' + p.d + ' of the month']];
    if (nth < 5) o.push(['nth', 'The ' + ORD[nth - 1] + ' ' + WD[p.w]]);
    if (last) o.push(['last', 'The last ' + WD[p.w]]);
    if (!o.some(x => x[0] === monthly)) monthly = 'day';
    monEl.innerHTML = o.map(x => '<label class="mcl-recur-radio"><input type="radio" name="mon" value="' + x[0] + '"' + (x[0] === monthly ? ' checked' : '') + '> ' + x[1] + '</label>').join('') +
      '<span class="mcl-recur-note" data-skip>Months without a ' + p.d + (p.d === 31 ? 'st' : 'th') + ' are skipped.</span>';
  }
  monEl.querySelector('[data-skip]').hidden = !(p.d > 28 && monthly === 'day');
}

function rule() {
  const start = fromIso(startEl.value), n = parseInt(intEl.value, 10), freq = freqEl.value;
  const end = (root.querySelector('input[name="end"]:checked') || {}).value || 'never';
  const until = fromIso(untilEl.value), count = parseInt(countEl.value, 10);
  return { start, n, freq, end, until, count };
}
function validate(r) {
  if (r.start == null) return ['start', 'Pick a start date.'];
  if (!(r.n >= 1 && r.n <= 99)) return ['int', 'Repeat every 1 to 99 ' + { d: 'days', w: 'weeks', m: 'months', y: 'years' }[r.freq] + '.'];
  if (r.freq === 'w' && !days.size) return ['days', 'Pick at least one weekday.'];
  if (r.end === 'until' && (r.until == null || r.until < r.start)) return ['until', 'The end date is before the series starts.'];
  if (r.end === 'count' && !(r.count >= 1 && r.count <= 99)) return ['count', 'End after 1 to 99 times.'];
  return null;
}

/* generate occurrences: RFC 5545 behaviour, months without the day are skipped */
function occurrences(r, limit) {
  const out = [], sp = P(r.start), cap = r.end === 'count' ? Math.min(r.count, limit) : limit;
  const ok = x => x >= r.start && (r.end !== 'until' || x <= r.until);
  const past = x => r.end === 'until' && x > r.until;
  for (let k = 0; k < MAXN && out.length < cap; k++) {
    let cand = [];
    if (r.freq === 'd') cand = [r.start + k * r.n];
    else if (r.freq === 'w') { const wk = r.start - sp.w + k * r.n * 7; cand = [...days].sort().map(w => wk + w); }
    else if (r.freq === 'm') {
      const mi = sp.m + k * r.n, y = sp.y + Math.floor(mi / 12), m = ((mi % 12) + 12) % 12, len = dim(y, m);
      if (monthly === 'day') { if (sp.d <= len) cand = [dn(y, m, sp.d)]; }
      else {
        const first = dn(y, m, 1), off = (sp.w - P(first).w + 7) % 7;
        if (monthly === 'nth') { const d = 1 + off + (Math.ceil(sp.d / 7) - 1) * 7; if (d <= len) cand = [dn(y, m, d)]; }
        else { let d = 1 + off; while (d + 7 <= len) d += 7; cand = [dn(y, m, d)]; }
      }
    } else {
      const y = sp.y + k * r.n;
      if (sp.d <= dim(y, sp.m)) cand = [dn(y, sp.m, sp.d)];
    }
    for (const c of cand) { if (out.length >= cap) break; if (past(c)) return out; if (ok(c)) out.push(c); }
    if (cand.length && past(cand[0])) break;
  }
  return out;
}

function summary(r, all, finite) {
  const unit = { d: 'day', w: 'week', m: 'month', y: 'year' }[r.freq];
  let s = r.n === 1 ? (r.freq === 'd' ? 'Daily' : r.freq === 'w' ? 'Weekly' : r.freq === 'm' ? 'Monthly' : 'Yearly') : 'Every ' + r.n + ' ' + unit + 's';
  const sp = P(r.start);
  if (r.freq === 'w') s += ' on ' + listJoin([...days].sort().map(w => WD[w]));
  if (r.freq === 'm') s += monthly === 'day' ? ' on day ' + sp.d : ' on the ' + (monthly === 'last' ? 'last' : ORD[Math.ceil(sp.d / 7) - 1]) + ' ' + WD[sp.w];
  if (r.freq === 'y') s += ' on ' + fMD.format(new Date(r.start * DAY));
  s = '<b>' + s + '</b>, from ' + fMD.format(new Date(r.start * DAY));
  if (r.end === 'until') s += ' until ' + fMDY.format(new Date(r.until * DAY));
  if (r.end === 'count') s += ', ' + r.count + (r.count === 1 ? ' time' : ' times');
  if (finite && all.length) s += ' — last on ' + fMDY.format(new Date(all[all.length - 1] * DAY));
  return s + '.';
}

function rel(n) {
  const d = n - today;
  if (Math.abs(d) < 14) return rtf.format(d, 'day');
  if (Math.abs(d) < 63) return rtf.format(Math.round(d / 7), 'week');
  return rtf.format(Math.round(d / 30.44), 'month');
}

/* FLIP: measure, re-key, invert, play — and ghost the rows that leave */
function renderList(items, lastN) {
  const before = new Map();
  const live = [...listEl.querySelectorAll('.mcl-recur-item:not(.mcl-recur-ghost)')];
  for (const el of live) before.set(el.dataset.k, el.getBoundingClientRect());
  const old = new Map(live.map(el => [el.dataset.k, el]));
  const base = listEl.getBoundingClientRect();
  const keep = items.map((n, i) => {
    const k = String(n);
    let el = old.get(k);
    if (!el) { el = document.createElement('li'); el.className = 'mcl-recur-item'; el.dataset.k = k; }
    old.delete(k);
    el.classList.toggle('is-last', n === lastN);
    el.innerHTML = '<i>' + String(i + 1).padStart(2, '0') + '</i><b>' + fRow.format(new Date(n * DAY)) + '<small>' + (P(n).y !== P(today).y ? P(n).y : '3:30 PM') + '</small></b><span>' + (n === lastN ? 'last · ' : '') + rel(n) + '</span>';
    return el;
  });
  const ghosts = RM.matches ? [] : [...old.values()].map(el => {
    const r = before.get(el.dataset.k), g = el;
    g.classList.add('mcl-recur-ghost'); g.style.top = (r.top - base.top + listEl.scrollTop) + 'px';
    return g;
  });
  listEl.replaceChildren(...keep, ...ghosts);
  if (!items.length) listEl.insertAdjacentHTML('afterbegin', '<li class="mcl-recur-empty">No dates to show yet — fix the rule above.</li>');
  if (RM.matches) return;
  ghosts.forEach(g => g.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(12px)' }], { duration: 220, easing: 'ease-in' }).onfinish = () => g.remove());
  keep.forEach((el, i) => {
    const a = before.get(el.dataset.k), b = el.getBoundingClientRect();
    if (a) { const dy = a.top - b.top; if (Math.abs(dy) > .5) el.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 480, easing: 'cubic-bezier(.2,.9,.25,1)' }); }
    else el.animate([{ opacity: 0, transform: 'translateX(-10px)' }, { opacity: 1, transform: 'none' }], { duration: 340, delay: i * 40, easing: 'cubic-bezier(.2,.9,.25,1)', fill: 'backwards' });
  });
}

function renderRail(r, all) {
  const w0 = r.start - P(r.start).w;
  let ticks = '', months = '', lastM = -1;
  all.filter(n => n < w0 + WINDOW).forEach((n, i) => { ticks += '<i style="--x:' + ((n - w0 + .5) / WINDOW * 100).toFixed(2) + ';--i:' + i + '"' + (i >= 6 ? ' class="is-more"' : '') + '></i>'; });
  const labels = [];
  for (let k = 0; k < 26; k++) {
    const m = P(w0 + k * 7).m;
    if (m !== lastM && k < 24) labels.push([k, fMon.format(new Date((w0 + k * 7) * DAY))]);
    lastM = m;
  }
  /* a month that only owns the first week or two gives way to the next label */
  labels.filter((l, i) => !(labels[i + 1] && labels[i + 1][0] - l[0] < 3))
    .forEach(l => { months += '<span style="--x:' + (l[0] / 26 * 100).toFixed(2) + '">' + l[1] + '</span>'; });
  railEl.innerHTML = ticks;
  monthsEl.innerHTML = months;
}

let lastErr = null;
function update() {
  const r = rule();
  root.querySelectorAll('[data-when]').forEach(el => { el.hidden = el.dataset.when !== r.freq; });
  [...freqEl.options].forEach(o => { o.textContent = { d: 'day', w: 'week', m: 'month', y: 'year' }[o.value] + (r.n === 1 ? '' : 's'); });
  decBtn.disabled = !(r.n > 1); incBtn.disabled = !(r.n < 99);
  untilEl.hidden = r.end !== 'until'; $('[data-countwrap]').hidden = r.end !== 'count';
  if (r.start != null) monthlyOptions(r.start);
  const err = validate(r);
  [startEl, intEl, untilEl, countEl].forEach(el => el.removeAttribute('aria-invalid'));
  if (err) {
    const el = { start: startEl, int: intEl, until: untilEl, count: countEl }[err[0]];
