    if (lastErr !== err[0] && !RM.matches) { sumEl.classList.remove('is-shake'); void sumEl.offsetWidth; sumEl.classList.add('is-shake'); }
    lastErr = err[0];
    totalEl.textContent = '';
    renderList([], null); railEl.innerHTML = '';
    return;
  }
  lastErr = null;
  sumEl.removeAttribute('data-bad');
  const finite = r.end !== 'never';
  const all = occurrences(r, finite ? 99 : 200);
  const lastN = finite ? all[all.length - 1] : null;
  sumEl.innerHTML = summary(r, all, finite);
  const inWin = all.filter(n => n < r.start - P(r.start).w + WINDOW).length;
  totalEl.textContent = finite ? all.length + (all.length === 1 ? ' date' : ' dates') + ' in total' : inWin + ' in the next 26 weeks';
  renderList(all.slice(0, finite ? all.length : 12), lastN);
  renderRail(r, all);
}

daysEl.addEventListener('click', e => {
  const b = e.target.closest('[data-w]');
  if (!b) return;
  const w = +b.dataset.w;
  days.has(w) ? days.delete(w) : days.add(w);
  b.setAttribute('aria-pressed', String(days.has(w)));
