});
daysEl.addEventListener('keydown', e => {
  const bs = [...daysEl.children], i = bs.indexOf(document.activeElement);
  const j = e.key === 'ArrowRight' ? i + 1 : e.key === 'ArrowLeft' ? i - 1 : -2;
  if (i < 0 || j === -2) return;
  e.preventDefault(); bs[(j + 7) % 7].focus();
});
decBtn.addEventListener('click', () => { intEl.value = Math.max(1, (parseInt(intEl.value, 10) || 1) - 1); update(); });
incBtn.addEventListener('click', () => { intEl.value = Math.min(99, (parseInt(intEl.value, 10) || 0) + 1); update(); });
intEl.addEventListener('keydown', e => {
  if (e.key === 'ArrowUp' || e.key === 'ArrowDown') { e.preventDefault(); (e.key === 'ArrowUp' ? incBtn : decBtn).click(); }
});
root.addEventListener('input', e => { if (e.target.matches('[data-int], [data-count], [data-start], [data-until]')) update(); });
root.addEventListener('change', e => {
  if (e.target.name === 'mon') monthly = e.target.value;
  if (e.target.name === 'end') { update(); return; }
  update();
});
root.addEventListener('submit', e => e.preventDefault());

update();

