@keyframes mcl-snooze-draw { from { stroke-dashoffset: var(--len); } }
@keyframes mcl-snooze-shake { 20%, 60% { translate: -4px 0; } 40%, 80% { translate: 4px 0; } }

.mcl-snooze {
  /* re-theme with these four */
  --mcl-snooze-bg: oklch(0.2 0.008 40);
  --mcl-snooze-ink: oklch(0.95 0.01 60);
  --mcl-snooze-accent: oklch(0.8 0.11 355);
  --mcl-snooze-time: oklch(0.84 0.09 155);
  --mcl-snooze-bad: oklch(0.7 0.17 30);

  --mcl-snooze-mute: color-mix(in oklch, var(--mcl-snooze-ink) 56%, var(--mcl-snooze-bg));
  --mcl-snooze-faint: color-mix(in oklch, var(--mcl-snooze-ink) 32%, var(--mcl-snooze-bg));
  --mcl-snooze-line: color-mix(in oklch, var(--mcl-snooze-ink) 11%, transparent);
  --mcl-snooze-raise: color-mix(in oklch, var(--mcl-snooze-ink) 5%, transparent);
  --mcl-snooze-hl: color-mix(in oklch, var(--mcl-snooze-accent) 14%, transparent);
  --mcl-snooze-out: cubic-bezier(.2, .9, .25, 1);
  --mcl-snooze-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.077 22.4%, 1.101 25.5%, 1.096 28.9%, 1.065 34.1%, 1.016 42.2%, 0.997 49.1%, 0.991 56.4%, 1.001 76.4%, 1);

  container-type: inline-size;
  position: relative; box-sizing: border-box; width: 100%; min-height: 158px;
  display: grid; gap: 14px; align-content: start;
  padding: 16px;
  border-radius: 18px; border: 1px solid var(--mcl-snooze-line);
  background: radial-gradient(120% 70% at 100% 0%, color-mix(in oklch, var(--mcl-snooze-accent) 9%, transparent), transparent 60%), var(--mcl-snooze-bg);
  color: var(--mcl-snooze-ink);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & button, & input { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--mcl-snooze-accent); outline-offset: 2px; }

  /* ---------- message context ---------- */
  & .mcl-snooze-msg { display: grid; grid-template-columns: 34px minmax(0, 1fr); gap: 10px; align-items: center; padding-bottom: 12px; border-bottom: 1px solid var(--mcl-snooze-line); }
  & .mcl-snooze-av { width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; font-size: 12px; font-weight: 700; background: oklch(0.45 0.08 200); color: oklch(0.95 0.03 200); }
  & .mcl-snooze-from { margin: 0; font-size: 11.5px; color: var(--mcl-snooze-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .mcl-snooze-subj { margin: 1px 0 0; font-size: 13.5px; font-weight: 650; letter-spacing: -.005em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

  /* ---------- picker ---------- */
  & .mcl-snooze-pick, & .mcl-snooze-done {
    transition: opacity .3s var(--mcl-snooze-out), translate .4s var(--mcl-snooze-out), filter .3s;
    @starting-style { opacity: 0; translate: 0 8px; filter: blur(4px); }
    &[hidden] { display: none; }
  }
  & .mcl-snooze-pick { display: grid; gap: 8px; }
  & .mcl-snooze-label { font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--mcl-snooze-accent); }
  & .mcl-snooze-field {
    position: relative; display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 8px;
    height: 40px; padding: 0 8px 0 11px; border-radius: 11px;
    background: var(--mcl-snooze-raise); box-shadow: inset 0 0 0 1px var(--mcl-snooze-line);
    transition: box-shadow .2s;
    & > svg { width: 16px; height: 16px; color: var(--mcl-snooze-mute); }
    &:focus-within { box-shadow: inset 0 0 0 1.5px var(--mcl-snooze-accent), 0 0 0 4px var(--mcl-snooze-hl); }
    &.is-shake { animation: mcl-snooze-shake .36s; }
  }
  /* the mirror sits exactly under the input text and paints tokens behind it */
  & .mcl-snooze-mirror, & .mcl-snooze-input {
    grid-column: 2; grid-row: 1; height: 100%; padding: 0; margin: 0; border: 0;
    font: 500 14px/40px system-ui, -apple-system, "Segoe UI", sans-serif; letter-spacing: 0; white-space: pre;
  }
  & .mcl-snooze-mirror {
    overflow: hidden; color: transparent; pointer-events: none;
    & mark { color: transparent; border-radius: 4px; padding: 2px 0; box-decoration-break: clone; transition: background-color .2s; }
    & mark[data-t="date"], & mark[data-t="rel"] { background: color-mix(in oklch, var(--mcl-snooze-accent) 24%, transparent); box-shadow: 0 2px 0 -0.5px var(--mcl-snooze-accent); }
    & mark[data-t="time"] { background: color-mix(in oklch, var(--mcl-snooze-time) 22%, transparent); box-shadow: 0 2px 0 -0.5px var(--mcl-snooze-time); }
    & mark[data-t="fill"] { background: none; }
    & mark[data-t="bad"] { background: none; text-decoration: wavy underline var(--mcl-snooze-bad); text-decoration-thickness: 1.5px; text-underline-offset: 4px; color: transparent; }
  }
  & .mcl-snooze-input {
    position: relative; width: 100%; background: none; outline: none; caret-color: var(--mcl-snooze-accent);
    &::placeholder { color: var(--mcl-snooze-faint); font-weight: 400; }
  }
  & .mcl-snooze-kbd {
    padding: 2px 6px; border-radius: 5px; font: 600 11px/1.2 ui-monospace, Menlo, monospace;
    background: var(--mcl-snooze-line); color: var(--mcl-snooze-mute);
    transition: opacity .2s, background-color .2s, color .2s;
  }
  &[data-ok] .mcl-snooze-kbd { background: var(--mcl-snooze-accent); color: var(--mcl-snooze-bg); }
  & .mcl-snooze-parse {
    margin: 0; min-height: 18px; display: flex; align-items: center; gap: 6px;
    font-size: 12px; color: var(--mcl-snooze-mute); text-wrap: pretty; font-variant-numeric: tabular-nums;
    & b { color: var(--mcl-snooze-ink); font-weight: 650; }
    & svg { width: 14px; height: 14px; }
    &[data-tone="bad"] { color: var(--mcl-snooze-bad); }
  }

  & .mcl-snooze-opts { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
  & .mcl-snooze-opts.is-quiet .mcl-snooze-opt { transition: none; }
  & .mcl-snooze-opt {
    display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 10px;
    height: 36px; padding: 0 10px; border-radius: 10px; cursor: pointer;
    transition: background-color .15s, translate .3s var(--mcl-snooze-spring);
    animation: none;
    & svg { width: 16px; height: 16px; color: var(--mcl-snooze-mute); }
    & b { font-weight: 550; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & time { font-size: 12px; color: var(--mcl-snooze-mute); font-variant-numeric: tabular-nums; white-space: nowrap; }
    &:hover { background: var(--mcl-snooze-raise); }
    &[aria-selected="true"] { background: var(--mcl-snooze-hl); & svg, & time { color: var(--mcl-snooze-accent); } }
    &.is-parsed { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mcl-snooze-accent) 35%, transparent);
      @starting-style { opacity: 0; translate: 0 -6px; }
      transition: background-color .15s, opacity .25s, translate .35s var(--mcl-snooze-spring);
    }
  }

  /* ---------- confirmation ---------- */
  & .mcl-snooze-done { display: grid; justify-items: center; text-align: center; gap: 2px; padding: 6px 0 2px; }
  & .mcl-snooze-check {
    width: 44px; height: 44px; margin-bottom: 6px; color: var(--mcl-snooze-accent); stroke-width: 2;
    & circle { --len: 107; stroke-dasharray: 107; animation: mcl-snooze-draw .6s var(--mcl-snooze-out) backwards; }
    & path { --len: 26; stroke-dasharray: 26; animation: mcl-snooze-draw .4s .35s var(--mcl-snooze-out) backwards; }
  }
  & .mcl-snooze-dlabel { margin: 0; font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--mcl-snooze-mute); }
  & .mcl-snooze-when { margin: 0; font-size: clamp(18px, 6.2cqi, 22px); font-weight: 680; letter-spacing: -.015em; font-variant-numeric: tabular-nums; text-wrap: balance; }
  & .mcl-snooze-rel { margin: 0; font-size: 12.5px; color: var(--mcl-snooze-mute); font-variant-numeric: tabular-nums; }
  & .mcl-snooze-actions {
    display: flex; gap: 8px; margin-top: 12px;
    & button { height: 34px; padding: 0 14px; border-radius: 10px; cursor: pointer; font-size: 13px; font-weight: 600; border: 1px solid var(--mcl-snooze-line); background: var(--mcl-snooze-raise); transition: background-color .15s, scale .3s var(--mcl-snooze-spring); }
    & button:hover { background: var(--mcl-snooze-line); }
    & button:active { scale: .96; }
    & [data-undo] { background: var(--mcl-snooze-ink); color: var(--mcl-snooze-bg); border-color: transparent; }
    & [data-undo]:hover { background: color-mix(in oklch, var(--mcl-snooze-ink) 88%, var(--mcl-snooze-bg)); }
  }

  @container (max-width: 290px) {
    & .mcl-snooze-opt { gap: 8px; padding: 0 8px; & time { font-size: 11px; } }
    & .mcl-snooze-kbd { display: none; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .mcl-snooze {
    & .mcl-snooze-pick, & .mcl-snooze-done { transition: opacity .2s; @starting-style { opacity: 0; translate: none; filter: none; } }
    & .mcl-snooze-field.is-shake { animation: none; }
    & .mcl-snooze-check circle, & .mcl-snooze-check path { animation: none; }
    & .mcl-snooze-opt.is-parsed { transition: background-color .15s, opacity .2s; @starting-style { opacity: 0; translate: none; } }
  }
}

