const $ = s => root.querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const uid = 'mcl-snooze-' + Math.random().toString(36).slice(2, 8);
const input = $('[data-input]'), mirror = $('[data-mirror]'), parseEl = $('[data-parse]'), optsEl = $('[data-opts]');
const pick = $('[data-pick]'), done = $('[data-done]'), whenEl = $('[data-when]'), relEl = $('[data-rel]'), field = $('.mcl-snooze-field');
input.id = uid + '-in'; $('[data-labelfor]').htmlFor = input.id; optsEl.id = uid + '-list'; input.setAttribute('aria-controls', optsEl.id);

const DAYS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const PARTS = { morning: 480, afternoon: 840, evening: 1080, tonight: 1200, night: 1200, noon: 720, midday: 720, midnight: 0, eod: 1020, lunch: 750 };
const UNITS = [[/^(m|min|mins|minute|minutes)$/, 6e4], [/^(h|hr|hrs|hour|hours)$/, 36e5], [/^(d|day|days)$/, 864e5, 'd'], [/^(w|wk|wks|week|weeks)$/, 6048e5, 'd'], [/^(mo|mos|month|months)$/, 0, 'm']];
const FILL = new Set(['at', 'on', 'the', 'by', 'until', 'til', 'till', 'around', '@', ',', 'for', 'from', 'now', 'of', 'and', '-']);
const esc = s => s.replace(/[&<>"]/g, c => '&#' + c.charCodeAt(0) + ';');
const day = w => DAYS.findIndex(d => w.length >= 3 && d.startsWith(w));
const mon = w => MONTHS.findIndex(m => w.length >= 3 && m.startsWith(w));
const unit = w => w && UNITS.find(u => u[0].test(w));
const numWord = w => w == null ? null : /^\d+(\.\d+)?$/.test(w) ? +w : { a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, ten: 10, few: 3, couple: 2 }[w] ?? null;

/* tokenize, keeping offsets so the mirror can paint each piece */
function lex(text) {
  const re = /(\d{1,2}:\d{2}\s*(?:am|pm|a|p)?)|(\d{1,2}\s*(?:am|pm|a\.m\.|p\.m\.))|(\d{1,2}\/\d{1,2}(?:\/\d{2,4})?)|(\d+(?:st|nd|rd|th)?)|([a-zà-ÿ]+)|(\S)/gi;
  const out = []; let m;
  while ((m = re.exec(text))) out.push({ s: m.index, e: m.index + m[0].length, v: m[0].toLowerCase(), raw: m[0], t: 'bad' });
  return out;
}
function clockOf(v) {
  let m = /^(\d{1,2})(?::(\d{2}))?\s*(am|pm|a|p|a\.m\.|p\.m\.)?$/.exec(v);
  if (!m) return null;
  let h = +m[1], mi = +(m[2] || 0), ap = m[3] ? m[3][0] : null;
  if (mi > 59 || h > 23 || (ap && (h < 1 || h > 12))) return null;
  if (ap === 'p' && h < 12) h += 12;
  if (ap === 'a' && h === 12) h = 0;
  return h * 60 + mi;
}

function parse(text, now) {
  const toks = lex(text);
  const t0 = new Date(now); t0.setHours(0, 0, 0, 0);
  let date = null, time = null, relMs = 0, relDays = 0, relMonths = 0, hasRel = false;
  const mark = (a, b, t) => { for (let k = a; k < b; k++) toks[k].t = t; };
  const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
  for (let i = 0; i < toks.length;) {
    const v = toks[i].v, n1 = toks[i + 1] && toks[i + 1].v, n2 = toks[i + 2] && toks[i + 2].v;
    if (FILL.has(v)) { mark(i, i + 1, 'fill'); i++; continue; }
    /* in 3 days · in an hour · in half an hour · 2 weeks */
    {
      let j = v === 'in' ? i + 1 : i, amt = numWord(toks[j] && toks[j].v);
      if (toks[j] && toks[j].v === 'half' && (toks[j + 1] || {}).v && /^an?$/.test(toks[j + 1].v)) { amt = .5; j++; }
      if (toks[j] && toks[j].v === 'couple' && toks[j + 1] && toks[j + 1].v === 'of') j++;
      const u = amt != null && unit(toks[j + 1] && toks[j + 1].v);
      if (u && (v === 'in' || /^\d/.test(v))) {
        if (u[2] === 'm') relMonths += amt; else if (u[2] === 'd') relDays += amt * u[1] / 864e5; else relMs += amt * u[1];
        hasRel = true; mark(i, j + 2, 'rel'); i = j + 2; continue;
      }
    }
    if (v === 'today') { date = t0; mark(i, i + 1, 'date'); i++; continue; }
    if (v === 'tonight') { date = t0; time = PARTS.tonight; mark(i, i + 1, 'date'); i++; continue; }
    if (/^(tomorrow|tmrw|tmr|tom)$/.test(v)) { date = addDays(t0, 1); mark(i, i + 1, 'date'); i++; continue; }
    if ((v === 'next' || v === 'this') && n1) {
      const wd = day(n1);
      if (wd >= 0) {
        const cur = (t0.getDay() + 6) % 7, tgt = (wd + 6) % 7;
        date = addDays(t0, v === 'next' ? 7 - cur + tgt : (tgt - cur + 7) % 7);
        mark(i, i + 2, 'date'); i += 2; continue;
      }
      if (n1 === 'week') { date = addDays(t0, 7 - (t0.getDay() + 6) % 7); mark(i, i + 2, 'date'); i += 2; continue; }
      if (n1 === 'weekend') { const toSat = (6 - t0.getDay() + 7) % 7; date = addDays(t0, v === 'next' ? toSat + 7 : toSat || (t0.getDay() === 6 ? 0 : 7)); time = time ?? 540; mark(i, i + 2, 'date'); i += 2; continue; }
      if (n1 === 'month') { date = new Date(t0.getFullYear(), t0.getMonth() + 1, 1); mark(i, i + 2, 'date'); i += 2; continue; }
    }
    if (v === 'weekend') { const toSat = (6 - t0.getDay() + 7) % 7; date = addDays(t0, toSat); time = time ?? 540; mark(i, i + 1, 'date'); i++; continue; }
    { const wd = day(v); if (wd >= 0) { const diff = (wd - t0.getDay() + 7) % 7 || 7; date = addDays(t0, diff); mark(i, i + 1, 'date'); i++; continue; } }
    /* dec 1 · december 1st 2026 · 1 dec */
    {
      let mo = mon(v), d = null, used = 1;
      if (mo >= 0 && n1 && /^\d{1,2}(st|nd|rd|th)?$/.test(n1)) { d = parseInt(n1, 10); used = 2; }
      else if (/^\d{1,2}(st|nd|rd|th)?$/.test(v) && n1 && mon(n1) >= 0) { d = parseInt(v, 10); mo = mon(n1); used = 2; }
      if (mo >= 0 && d) {
        let y = t0.getFullYear();
        const third = toks[i + used] && toks[i + used].v;
        if (third && /^20\d\d$/.test(third)) { y = +third; used++; }
        let dt = new Date(y, mo, d);
        if (dt.getMonth() !== mo) { mark(i, i + used, 'bad'); i += used; continue; }
        if (used === 2 && dt < t0) dt = new Date(y + 1, mo, d);
        date = dt; mark(i, i + used, 'date'); i += used; continue;
      }
    }
    if (/^\d{1,2}\/\d{1,2}/.test(v)) {
      const [m, d, yy] = v.split('/').map(Number);
      let dt = new Date(yy ? (yy < 100 ? 2000 + yy : yy) : t0.getFullYear(), m - 1, d);
      if (dt.getMonth() === m - 1) { if (!yy && dt < t0) dt.setFullYear(dt.getFullYear() + 1); date = dt; mark(i, i + 1, 'date'); i++; continue; }
    }
    if (v in PARTS) { time = PARTS[v]; mark(i, i + 1, 'time'); i++; continue; }
    if (/^\d/.test(v)) {
      let c = clockOf(v.replace(/\s+/g, ''));
      /* "9" after "at": read 7–11 as morning, 1–6 as afternoon */
      if (c != null && /^\d{1,2}$/.test(v) && !(toks[i - 1] && toks[i - 1].v === 'at')) c = null;
      if (c != null && /^\d{1,2}$/.test(v)) { const h = +v; c = (h >= 1 && h <= 6 ? h + 12 : h === 12 ? 12 : h) * 60; }
      if (c != null) { time = c; mark(i, i + 1, 'time'); i++; continue; }
    }
    i++;
  }
  const bad = toks.filter(t => t.t === 'bad');
  if (!toks.length) return { toks, empty: true };
  if (bad.length) return { toks, error: 'Can’t read “' + bad.map(t => t.raw).join(' ') + '” — try “tomorrow 9am” or “in 2 hours”.' };
